{
  "name": "Atomic Words",
  "description": "A 2D mobile word puzzle game featuring an atomic theme, dynamic letter grids generated by AI, and a competitive leaderboard."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface User {
  username: string;
  id: string;
}

export interface LeaderboardEntry {
  username: string;
  score: number;
  date: string;
}

export interface GridCell {
  id: string;
  char: string;
  x: number;
  y: number;
}

export interface GameConfig {
  gridSize: number; // usually 4 or 5
  timeLimit: number; // in seconds
}

export interface GameData {
  grid: string[][];
  validWords: string[];
}

export enum GameStatus {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  PLAYING = 'PLAYING',
  FINISHED = 'FINISHED'
}

import { GoogleGenAI, Type } from "@google/genai";
import { GameData } from "../types";

const apiKey = process.env.API_KEY || ''; // Fallback for safety, though env is expected
const ai = new GoogleGenAI({ apiKey });

// Cache structure to prevent excessive API calls during development/testing
const CACHE_KEY = 'atomic_words_cache';

export const generateGameLevel = async (gridSize: number = 4): Promise<GameData> => {
  try {
    const model = 'gemini-2.5-flash';

    const prompt = `
      Create a ${gridSize}x${gridSize} grid of letters for a word search game (Boggle style).
      The grid must contain at least 25 valid English words that can be formed by connecting adjacent letters (horizontally, vertically, or diagonally).

      Return a JSON object with:
      1. 'grid': A 2D array of single upper-case characters representing the rows.
      2. 'validWords': An array of strings containing ALL the valid English words (length > 2) found in this specific grid.

      Ensure common vowels and consonants are placed to maximize word formation.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            grid: {
              type: Type.ARRAY,
              items: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              }
            },
            validWords: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["grid", "validWords"]
        }
      }
    });

    if (response.text) {
      const data = JSON.parse(response.text) as GameData;
      // Normalize data
      data.validWords = data.validWords.map(w => w.toUpperCase());
      return data;
    }

    throw new Error("Empty response from AI");

  } catch (error) {
    console.error("AI Generation failed, using fallback", error);
    // Fallback static grid if API fails or quota exceeded
    return {
      grid: [
        ['A', 'T', 'O', 'M'],
        ['R', 'E', 'N', 'I'],
        ['G', 'Y', 'S', 'C'],
        ['B', 'O', 'L', 'T']
      ],
      validWords: ['ATOM', 'ATOMIC', 'ENERGY', 'BOLT', 'CORE', 'ION', 'GAS', 'REST', 'TEST', 'MORE', 'ORE', 'NET', 'TEN', 'ROT', 'NOT', 'TON', 'SON', 'SET', 'TOE']
    };
  }
};

export const getHint = async (currentGrid: string[][], foundWords: string[], allValidWords: string[]): Promise<string> => {
  // Simple client-side logic is faster for hints than calling AI again, 
  // but we can simulate an "AI Assistant" feel.
  const remaining = allValidWords.filter(w => !foundWords.includes(w));
  if (remaining.length === 0) return "No more words!";

  // Return a random word that hasn't been found yet
  const word = remaining[Math.floor(Math.random() * remaining.length)];
  return `Try looking for a word starting with '${word[0]}'`;
};

import { LeaderboardEntry, User } from "../types";

const USER_KEY = 'atomic_user';
const SCORES_KEY = 'atomic_scores';

export const saveUser = (user: User) => {
  localStorage.setItem(USER_KEY, JSON.stringify(user));
};

export const getUser = (): User | null => {
  const data = localStorage.getItem(USER_KEY);
  return data ? JSON.parse(data) : null;
};

export const saveScore = (entry: LeaderboardEntry) => {
  const scores = getScores();
  scores.push(entry);
  // Sort by score desc
  scores.sort((a, b) => b.score - a.score);
  // Keep top 20
  const topScores = scores.slice(0, 20);
  localStorage.setItem(SCORES_KEY, JSON.stringify(topScores));
};

export const getScores = (): LeaderboardEntry[] => {
  const data = localStorage.getItem(SCORES_KEY);
  return data ? JSON.parse(data) : [];
};

import React, { useMemo } from 'react';

interface AtomicBackgroundProps {
  darkMode: boolean;
}

const AtomicBackground: React.FC<AtomicBackgroundProps> = ({ darkMode }) => {
  // Generate random letters for the background texture
  const letters = useMemo(() => {
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    return Array.from({ length: 100 }, () => chars[Math.floor(Math.random() * chars.length)]);
  }, []);

  return (
    <div className={`fixed inset-0 -z-10 overflow-hidden transition-colors duration-500 ${darkMode ? 'bg-atomic-dark' : 'bg-gray-100'}`}>
      {/* Dynamic Embossed Letter Grid */}
      <div className="absolute inset-0 grid grid-cols-10 opacity-10 pointer-events-none select-none">
        {letters.map((char, i) => (
          <div 
            key={i} 
            className={`
              flex items-center justify-center text-4xl font-black
              ${darkMode ? 'text-gray-800' : 'text-gray-300'}
            `}
            style={{
              transform: `rotate(${Math.random() * 30 - 15}deg)`,
              textShadow: darkMode 
                ? '1px 1px 0 rgba(255,255,255,0.1), -1px -1px 0 rgba(0,0,0,0.5)' 
                : '-1px -1px 0 rgba(255,255,255,0.8), 1px 1px 0 rgba(0,0,0,0.1)'
            }}
          >
            {char}
          </div>
        ))}
      </div>

      {/* Atomic Overlay Gradient */}
      <div className={`absolute inset-0 bg-gradient-to-br ${
        darkMode 
          ? 'from-transparent via-atomic-dark/80 to-atomic-blue/10' 
          : 'from-transparent via-white/80 to-atomic-orange/10'
      }`} />
    </div>
