          className="px-6 py-4 rounded-full bg-white/10 backdrop-blur-md border border-white/20 text-center text-xl font-bold placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-atomic-blue shadow-lg transition-all"
        />
        <button 
          type="submit"
          className="bg-atomic-neon text-atomic-dark font-black py-4 rounded-full uppercase tracking-widest hover:scale-105 transition-transform shadow-[0_0_20px_rgba(57,255,20,0.5)]"
        >
          Initialize
        </button>
      </form>
    </div>
  );
};

// Main Game Screen
const GameScreen: React.FC<{ 
  user: User, 
  onExit: () => void 
}> = ({ user, onExit }) => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.LOADING);
  const [gameData, setGameData] = useState<GameData | null>(null);
  const [selectedCells, setSelectedCells] = useState<GridCell[]>([]);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(120);
  const [isDragging, setIsDragging] = useState(false);
  const [hintMessage, setHintMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const gridRef = useRef<HTMLDivElement>(null);

  // Initialize Game
  useEffect(() => {
    const init = async () => {
      try {
        setError(null);
        setStatus(GameStatus.LOADING);
        const data = await GeminiService.generateGameLevel(4);
        setGameData(data);
        setStatus(GameStatus.PLAYING);
      } catch (e) {
        console.error(e);
        setError("System Failure. Grid construction interrupted.");
        setStatus(GameStatus.IDLE); // Break the loading loop
      }
    };
    init();
  }, []);

  // Timer
  useEffect(() => {
    if (status !== GameStatus.PLAYING) return;
    if (timeLeft <= 0) {
      setStatus(GameStatus.FINISHED);
      StorageService.saveScore({
        username: user.username,
        score: score,
        date: new Date().toISOString()
      });
      return;
    }
    const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(timer);
  }, [status, timeLeft, score, user.username]);

  // Input Handling
  const getCellFromTouch = (clientX: number, clientY: number): GridCell | null => {
    if (!gameData || !gridRef.current) return null;

    // Find element under touch
    const element = document.elementFromPoint(clientX, clientY);
    const cellId = element?.getAttribute('data-cell-id');

    if (cellId) {
      const [y, x] = cellId.split('-').map(Number);
      return { id: cellId, char: gameData.grid[y][x], x, y };
    }
    return null;
  };

  const handleStart = (cell: GridCell) => {
    if (status !== GameStatus.PLAYING) return;
    setIsDragging(true);
    setSelectedCells([cell]);
    setHintMessage(null); // Clear hint on interaction
  };

  const handleMove = (cell: GridCell) => {
    if (!isDragging || status !== GameStatus.PLAYING) return;

    // Check if cell is adjacent to last selected
    const last = selectedCells[selectedCells.length - 1];

    // Check if going back (undo selection)
    if (selectedCells.length > 1 && selectedCells[selectedCells.length - 2].id === cell.id) {
       setSelectedCells(prev => prev.slice(0, -1));
       return;
    }

    // Check valid adjacency (including diagonals) and not already selected
    const isAdjacent = Math.abs(last.x - cell.x) <= 1 && Math.abs(last.y - cell.y) <= 1;
    const isAlreadySelected = selectedCells.some(c => c.id === cell.id);

    if (isAdjacent && !isAlreadySelected) {
      setSelectedCells(prev => [...prev, cell]);
    }
  };

  const handleEnd = () => {
    setIsDragging(false);
    if (selectedCells.length === 0) return;

    const word = selectedCells.map(c => c.char).join('');
    validateWord(word);
    setSelectedCells([]);
  };

  const validateWord = (word: string) => {
    if (!gameData) return;

    if (word.length < 3) return; // Too short, just ignore
    if (foundWords.includes(word)) {
        setHintMessage("Already found!");
        setTimeout(() => setHintMessage(null), 1500);
        return;
    }

    if (gameData.validWords.includes(word)) {
      // Success!
      const points = calculateScore(word.length);
      setScore(prev => prev + points);
      setFoundWords(prev => [word, ...prev]);
    } else {
      // Invalid
      setHintMessage("Not in dictionary");
      setTimeout(() => setHintMessage(null), 1500);
    }
  };

  const calculateScore = (len: number) => {
    if (len === 3) return 100;
    if (len === 4) return 200;
    if (len >= 5) return 400 + (len - 5) * 100;
    return 0;
  };

  const requestHint = async () => {
     if (!gameData) return;
     setScore(prev => Math.max(0, prev - 50)); // Penalty for hint
     const hint = await GeminiService.getHint(gameData.grid, foundWords, gameData.validWords);
     setHintMessage(hint);
  };

  // Render Logic
  if (status === GameStatus.LOADING) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
        <AtomSpinner />
        <p className="animate-pulse text-xl font-bold text-atomic-blue">Constructing Grid...</p>
        <p className="text-xs text-gray-500">Retrieving Dictionary Protocols...</p>
      </div>
    );
  }

  if (error || status === GameStatus.IDLE) {
    return (
        <div className="flex flex-col items-center justify-center h-[60vh] gap-4 p-8 text-center">
            <AlertTriangle className="text-red-500 w-16 h-16" />
            <h3 className="text-2xl font-bold text-white">Connection Error</h3>
            <p className="text-gray-400">{error || "Unknown error occurred."}</p>
            <div className="flex gap-4 mt-4">
                <button onClick={onExit} className="px-6 py-3 rounded-xl bg-gray-700 text-white font-bold">Menu</button>
                <button onClick={() => window.location.reload()} className="px-6 py-3 rounded-xl bg-atomic-blue text-atomic-dark font-bold">Retry</button>
            </div>
        </div>
    );
  }

  if (status === GameStatus.FINISHED) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-6 animate-in zoom-in">
        <h2 className="text-4xl font-black text-atomic-neon">LEVEL COMPLETE</h2>
        <div className="p-8 bg-white/10 backdrop-blur-lg rounded-2xl border border-white/20 text-center">
          <p className="text-gray-400 uppercase tracking-widest text-sm mb-2">Final Score</p>
          <p className="text-6xl font-black">{score}</p>
        </div>
        <div className="flex gap-4">
            <button onClick={onExit} className="px-6 py-3 rounded-xl bg-gray-600 text-white font-bold hover:bg-gray-500">
                Menu
            </button>
            <button onClick={() => window.location.reload()} className="px-6 py-3 rounded-xl bg-atomic-blue text-atomic-dark font-bold hover:bg-cyan-300">
                Play Again
            </button>
        </div>
      </div>
    );
  }

  const currentWord = selectedCells.map(c => c.char).join('');

  return (
    <div className="flex flex-col h-full max-w-md mx-auto relative">
      {/* Header */}
      <div className="flex justify-between items-center px-4 py-2 bg-white/5 backdrop-blur-md rounded-b-2xl mb-4 shadow-lg border-b border-white/10">
        <div className="flex flex-col">
            <span className="text-xs text-gray-400 uppercase">Score</span>
            <span className="text-2xl font-black text-atomic-neon">{score}</span>
        </div>
        <div className="flex items-center gap-2">
            <Logo size="sm" />
        </div>
        <div className="flex flex-col items-end">
            <span className="text-xs text-gray-400 uppercase">Time</span>
            <span className={`text-2xl font-black ${timeLeft < 30 ? 'text-red-500 animate-pulse' : 'text-white'}`}>
                {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
            </span>
        </div>
      </div>

      {/* Message/Hint Area */}
      <div className="h-8 flex justify-center items-center mb-2">
        {hintMessage && (
            <span className="px-3 py-1 bg-atomic-orange/20 text-atomic-orange border border-atomic-orange/50 rounded-full text-sm font-bold animate-in slide-in-from-top">
                {hintMessage}
            </span>
        )}
      </div>

      {/* Word Preview */}
      <div className="h-16 flex items-center justify-center mb-4">
        <div className={`text-4xl font-black tracking-widest transition-all ${currentWord.length > 0 ? 'scale-110 text-white' : 'scale-100 text-gray-500/50'}`}>
             {currentWord || "SWIPE"}
        </div>
      </div>

      {/* The Grid */}
      <div 
        ref={gridRef}
        className="aspect-square w-full p-4 touch-none select-none"
        onMouseLeave={handleEnd}
        onMouseUp={handleEnd}
        onTouchEnd={handleEnd}
      >
        <div 
            className="grid grid-cols-4 gap-3 h-full"
            onTouchMove={(e) => {
                const touch = e.touches[0];
                const cell = getCellFromTouch(touch.clientX, touch.clientY);
                if (cell) handleMove(cell);
            }}
        >
            {gameData?.grid.map((row, y) => 
                row.map((char, x) => {
                    const isSelected = selectedCells.some(c => c.x === x && c.y === y);
                    const isLast = selectedCells.length > 0 && selectedCells[selectedCells.length-1].x === x && selectedCells[selectedCells.length-1].y === y;
                    const cellData: GridCell = { id: `${y}-${x}`, char, x, y };

                    return (
                        <div
                            key={`${y}-${x}`}
                            data-cell-id={`${y}-${x}`}
                            onMouseDown={() => handleStart(cellData)}
                            onMouseEnter={() => handleMove(cellData)}
                            className={`
                                relative flex items-center justify-center text-3xl font-bold rounded-xl cursor-pointer transition-all duration-150
                                shadow-[inset_0_-4px_4px_rgba(0,0,0,0.2)]
                                ${isSelected 
                                    ? 'bg-atomic-blue text-atomic-dark scale-95 shadow-[0_0_15px_rgba(0,243,255,0.6)] z-10' 
                                    : 'bg-white/10 hover:bg-white/20 text-current backdrop-blur-sm border border-white/10'}
                            `}
                        >
                            {char}
                        </div>
                    );
                })
            )}
        </div>
      </div>

      {/* Controls */}
      <div className="flex justify-around items-center px-8 mt-4">
         <button onClick={onExit} className="p-3 rounded-full bg-red-500/20 text-red-500 hover:bg-red-500 hover:text-white transition-colors">
            <X size={24} />
         </button>
         <button 
            onClick={requestHint}
            className="flex items-center gap-2 px-6 py-3 rounded-full bg-atomic-orange text-white font-bold shadow-lg hover:brightness-110 active:scale-95 transition-all"
         >
            <Lightbulb size={20} /> Hint
         </button>
         <div className="p-3 rounded-full bg-atomic-neon/20 text-atomic-neon">
            <Check size={24} />
         </div>
      </div>

      {/* Found Words List (Scrollable Footer) */}
      <div className="flex-1 overflow-hidden mt-6 bg-black/20 rounded-t-2xl backdrop-blur-md border-t border-white/10">
         <div className="p-4">
             <div className="flex justify-between items-baseline mb-2">
                 <h3 className="text-xs font-bold uppercase text-gray-400">Found Words ({foundWords.length})</h3>
                 <span className="text-[10px] text-gray-600">Total Possible: {gameData?.validWords.length}</span>
             </div>
             <div className="flex flex-wrap gap-2 overflow-y-auto max-h-[20vh]">
                 {foundWords.map((w, i) => (
                     <span key={i} className="px-3 py-1 bg-white/10 rounded-md text-sm font-medium animate-in zoom-in">{w}</span>
                 ))}
                 {foundWords.length === 0 && <span className="text-gray-500 italic text-sm">Start swiping...</span>}
             </div>
         </div>
      </div>
    </div>
  );
};

