function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'HOME' | 'GAME' | 'SCORES'>('HOME');
  const [darkMode, setDarkMode] = useState(true);

  useEffect(() => {
    const saved = StorageService.getUser();
    if (saved) setUser(saved);
  }, []);

  const toggleTheme = () => {
    setDarkMode(!darkMode);
  };

  return (
    <div className={`min-h-screen font-sans transition-colors duration-500 ${darkMode ? 'text-white' : 'text-slate-800'}`}>
      <AtomicBackground darkMode={darkMode} />

      {/* App Container */}
      <div className="relative z-10 container mx-auto h-screen flex flex-col">

        {/* Top Bar (Global) */}
        {user && view === 'HOME' && (
             <div className="flex justify-between items-center p-4">
                <button onClick={() => { StorageService.saveUser({username:'', id:''}); setUser(null); }} className="p-2 rounded-full hover:bg-white/10 text-gray-400">
                    <LogOut size={20} />
                </button>
                <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-white/10">
                    {darkMode ? <Sun size={20} /> : <Moon size={20} />}
                </button>
             </div>
        )}

        {/* View Routing */}
        <main className="flex-1 overflow-hidden">
            {!user ? (
                <LoginScreen onLogin={setUser} />
            ) : view === 'HOME' ? (
                <div className="flex flex-col items-center justify-center h-[70vh] gap-8 animate-in fade-in">
                    <Logo size="lg" />
                    <div className="flex flex-col gap-4 w-64">
                        <button 
                            onClick={() => setView('GAME')}
                            className="group relative px-8 py-4 bg-atomic-blue text-atomic-dark font-black text-xl rounded-xl shadow-[0_0_20px_rgba(0,243,255,0.4)] hover:scale-105 transition-all overflow-hidden"
