    e.preventDefault();
    setError(null);

    if (username.length < 3 || password.length < 3) {
      setError("Username and password must be at least 3 characters.");
      return;
    }

    if (isRegistering) {
      const result = StorageService.registerUser(username, password);
      if (result.success && result.user) {
        onLogin(result.user);
      } else {
        setError(result.message || "Registration failed.");
      }
    } else {
      const result = StorageService.loginUser(username, password);
      if (result.success && result.user) {
        onLogin(result.user);
      } else {
        setError(result.message || "Login failed.");
