          className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'AUDIO' ? 'bg-atomic-neon text-atomic-dark shadow-lg' : 'text-gray-400 hover:text-white'}`}
        >
          Sounds
        </button>
      </div>

      <div className="bg-black/20 backdrop-blur-md rounded-2xl border border-white/10 p-6 flex-1 overflow-y-auto">
        {activeTab === 'ACCOUNT' ? (
          <div className="flex flex-col gap-6">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Username</label>
              <div className="relative">
                <input 
                  type="text" 
