            <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Email</label>
                <div className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-gray-400 italic cursor-not-allowed">
                    {user.email}
                </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-2">New Password</label>
              <input 
                type="password" 
                placeholder="Leave blank to keep current"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-atomic-neon placeholder:text-gray-600"
              />
            </div>

            <div className="flex items-center justify-between p-4 bg-white/5 rounded-xl border border-white/10">
                <div className="flex flex-col">
                    <span className="text-sm font-bold text-white">Communications</span>
                    <span className="text-[10px] text-gray-400">Receive newsletters & score updates via email.</span>
                </div>
                <button 
                    onClick={() => setComms(!comms)}
                    className={`w-12 h-6 rounded-full transition-colors relative ${comms ? 'bg-atomic-neon' : 'bg-gray-600'}`}
                >
                    <div className={`absolute top-1 left-1 bg-white w-4 h-4 rounded-full transition-transform ${comms ? 'translate-x-6' : ''}`} />
                </button>
            </div>

            <button 
              onClick={handleUpdateAccount}
              className="mt-4 w-full py-4 bg-white/10 hover:bg-white/20 border border-white/20 rounded-xl font-bold text-atomic-blue transition-colors"
            >
              Update Profile
            </button>
          </div>
        ) : (
          <div className="flex flex-col gap-8">
             <div className="space-y-4">
               <div className="flex items-center gap-3 text-atomic-neon">
                 <Volume2 size={20} />
                 <span className="font-bold uppercase text-sm">Sound Effects</span>
               </div>
               <input 
                 type="range" min="0" max="100" 
                 value={sfxVol} onChange={(e) => setSfxVol(Number(e.target.value))}
                 className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-atomic-neon"
               />
               <div className="text-right text-xs font-mono text-gray-400">{sfxVol}%</div>
