// --- Main App Component ---

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'HOME' | 'GAME' | 'SCORES' | 'SETTINGS'>('HOME');
  const [darkMode, setDarkMode] = useState(true);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.NORMAL);

  useEffect(() => {
    const saved = StorageService.getSession();
    if (saved) setUser(saved);
  }, []);

  const handleLogout = () => {
    StorageService.clearSession();
    setUser(null);
    setView('HOME');
  };

  const toggleTheme = () => {
    setDarkMode(!darkMode);
  };

  return (
    <div className={`min-h-screen font-sans transition-colors duration-500 ${darkMode ? 'text-white' : 'text-slate-800'}`}>
      <AtomicBackground darkMode={darkMode} />

      {/* App Container */}
      <div className="relative z-10 container mx-auto h-screen flex flex-col">

        {/* Persistent Top Bar */}
         <div className="flex justify-between items-center p-4">
            {user && view === 'HOME' ? (
                <button onClick={handleLogout} className="p-2 rounded-full hover:bg-white/10 text-gray-400">
                    <LogOut size={20} />
                </button>
            ) : <div className="w-10"></div>}

            <div className="flex gap-2">
               {user && view === 'HOME' && (
                   <button onClick={() => setView('SETTINGS')} className="p-2 rounded-full hover:bg-white/10 text-gray-300">
                      <Settings size={20} />
                   </button>
               )}
               <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-white/10 transition-colors bg-white/5 backdrop-blur-sm">
                  {darkMode ? <Sun size={20} /> : <Moon size={20} />}
               </button>
            </div>
         </div>

        {/* View Routing */}
        <main className="flex-1 overflow-hidden">
            {!user ? (
                <LoginScreen onLogin={setUser} />
            ) : view === 'HOME' ? (
                <div className="flex flex-col items-center justify-center h-[70vh] gap-8 animate-in fade-in">
