const SettingsScreen: React.FC<{ user: User, onBack: () => void, onUpdateUser: (u: User) => void }> = ({ user, onBack, onUpdateUser }) => {
  const [activeTab, setActiveTab] = useState<'ACCOUNT' | 'AUDIO'>('ACCOUNT');

  // Account State
  const [newUsername, setNewUsername] = useState(user.username);
  const [newPassword, setNewPassword] = useState('');
  const [comms, setComms] = useState(user.settings.communications ?? true);
  const [message, setMessage] = useState<{type: 'success'|'error', text: string} | null>(null);

  // Audio State
  const [sfxVol, setSfxVol] = useState(user.settings.sfxVolume);
  const [musicVol, setMusicVol] = useState(user.settings.musicVolume);

  // 60 Days in ms
  const LOCKOUT_PERIOD = 60 * 24 * 60 * 60 * 1000;
  const daysSinceChange = (Date.now() - user.lastUsernameChange) / (1000 * 60 * 60 * 24);
  const canChangeUsername = daysSinceChange > 60 || user.lastUsernameChange === 0; 
  const daysRemaining = Math.ceil(60 - daysSinceChange);

  const handleUpdateAccount = () => {
    setMessage(null);
    const updatedUser = { ...user };
    let changed = false;

    if (newUsername !== user.username) {
      if (newUsername.length < 3) {
        setMessage({type: 'error', text: 'Username too short.'});
        return;
      }
      updatedUser.username = newUsername;
      updatedUser.lastUsernameChange = Date.now();
      changed = true;
    }

    if (newPassword.length > 0) {
      if (newPassword.length < 3) {
        setMessage({type: 'error', text: 'Password too short.'});
        return;
      }
      updatedUser.password = newPassword;
      changed = true;
    }

    if (comms !== user.settings.communications) {
        updatedUser.settings.communications = comms;
        changed = true;
    }

    if (changed) {
      const result = StorageService.updateUserProfile(updatedUser);
      if (result.success) {
        onUpdateUser(updatedUser);
        setMessage({type: 'success', text: 'Profile updated successfully.'});
        setNewPassword('');
      } else {
        setMessage({type: 'error', text: result.message || 'Update failed.'});
      }
    } else {
        setMessage({type: 'success', text: 'No changes detected.'});
    }
  };

  const handleUpdateAudio = () => {
    const updatedUser = { 
      ...user, 
      settings: { 
        ...user.settings,
        sfxVolume: sfxVol, 
        musicVolume: musicVol 
      } 
    };
    const result = StorageService.updateUserProfile(updatedUser);
    if (result.success) {
      onUpdateUser(updatedUser);
      setMessage({type: 'success', text: 'Audio settings saved.'});
    }
  };

