  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMsg(null);

    if (viewState === 'FORGOT') {
      const result = StorageService.requestPasswordReset(email);
      if (result.success) {
        setSuccessMsg(result.message);
      } else {
