      {isPirate ? (
         // Eyepatch overrides right eye
         <g>
            <circle cx="57" cy="38" r="3.5" fill="black" />
            <path d="M57 38 L70 28" stroke="black" strokeWidth="1.5" />
         </g>
      ) : (
         <circle cx="57" cy="38" r="2.5" fill="black" />
      )}

      {/* Mouth */}
      <path d="M40 50 Q50 55 60 50" stroke="black" strokeWidth="1.5" fill="none" />

      {/* Beard */}
      {config.beard === 'stubble' && (
          <path d="M35 50 Q50 65 65 50" stroke="rgba(0,0,0,0.2)" strokeWidth="4" fill="none" strokeDasharray="1 2" />
      )}
      {config.beard === 'full' && (
          <path d="M30 45 Q50 70 70 45 L70 45 Q50 60 30 45 Z" fill={config.hairColor} />
      )}

      {/* Hair */}
      {config.hairStyle === 'short' && (
          <path d="M30 40 Q50 10 70 40 L70 30 Q50 0 30 30 Z" fill={config.hairColor} />
      )}
      {config.hairStyle === 'spiky' && (
          <path d="M30 35 L40 20 L50 35 L60 15 L70 35 L70 40 Q50 45 30 40 Z" fill={config.hairColor} />
      )}
      {config.hairStyle === 'long' && (
           <path d="M30 40 Q20 80 25 80 L75 80 Q80 80 70 40 Q50 10 30 40 Z" fill={config.hairColor} />
      )}

      {/* Accessories */}
      {config.accessory === 'glasses' && !isPirate && (
          <g>
              <circle cx="43" cy="38" r="6" stroke="black" strokeWidth="1" fill="rgba(255,255,255,0.3)" />
              <circle cx="57" cy="38" r="6" stroke="black" strokeWidth="1" fill="rgba(255,255,255,0.3)" />
              <line x1="49" y1="38" x2="51" y2="38" stroke="black" strokeWidth="1" />
          </g>
      )}
       {config.accessory === 'hat' && (
           <path d="M25 30 L75 30 L65 15 L35 15 Z" fill="#333" />
      )}

      {/* Pirate Parrot */}
      {isPirate && (
          <g transform="translate(65, 65) scale(0.3)">
              <path d="M10 30 Q10 0 30 0 Q50 0 50 30 L50 50 L10 50 Z" fill="red" />
              <circle cx="35" cy="15" r="5" fill="white" />
              <circle cx="36" cy="15" r="2" fill="black" />
              <path d="M40 15 L50 20 L40 25 Z" fill="yellow" />
              <path d="M0 30 L20 30 L10 50 Z" fill="blue" />
          </g>
      )}

    </svg>
  );
};

