// Login / Register / Forgot Password Screen
const LoginScreen: React.FC<{ onLogin: (u: User) => void }> = ({ onLogin }) => {
  const [viewState, setViewState] = useState<'LOGIN' | 'REGISTER' | 'FORGOT'>('LOGIN');
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMsg(null);

    if (viewState === 'FORGOT') {
      const result = StorageService.requestPasswordReset(email);
      if (result.success) {
        setSuccessMsg(result.message);
      } else {
        setError(result.message);
      }
      return;
    }

    if (viewState === 'REGISTER') {
      if (!email.includes('@')) {
         setError("Valid email required.");
         return;
      }
      const result = StorageService.registerUser(username, email, password);
      if (result.success && result.user) {
        onLogin(result.user);
      } else {
        setError(result.message || "Registration failed.");
      }
    } else {
      const result = StorageService.loginUser(username, password);
      if (result.success && result.user) {
        onLogin(result.user);
      } else {
        setError(result.message || "Login failed.");
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] gap-8 p-4 animate-in fade-in zoom-in duration-500">
      <Logo size="lg" />

      <div className="w-full max-w-xs bg-white/60 dark:bg-black/20 backdrop-blur-xl p-6 rounded-3xl border border-black/5 dark:border-white/10 shadow-2xl">
        <h2 className="text-center text-xl font-black text-slate-900 dark:text-white mb-6 uppercase tracking-wider">
          {viewState === 'REGISTER' ? 'New Agent Profile' : viewState === 'FORGOT' ? 'Reset Protocols' : 'Agent Login'}
        </h2>

        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          {viewState !== 'FORGOT' && (
             <div className="relative group">
               <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 dark:text-gray-400 group-focus-within:text-atomic-blue transition-colors" size={20} />
               <input
                 type="text"
                 placeholder="Username"
                 value={username}
                 onChange={(e) => setUsername(e.target.value)}
                 className="w-full pl-12 pr-4 py-3 rounded-xl bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/10 text-slate-900 dark:text-white placeholder:text-slate-500 dark:placeholder:text-gray-500 focus:outline-none focus:ring-2 focus:ring-atomic-blue transition-all"
               />
             </div>
          )}

          {(viewState === 'REGISTER' || viewState === 'FORGOT') && (
            <div className="relative group">
              <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 dark:text-gray-400 group-focus-within:text-atomic-orange transition-colors" size={20} />
              <input
                type="email"
                placeholder="Email Address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full pl-12 pr-4 py-3 rounded-xl bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/10 text-slate-900 dark:text-white placeholder:text-slate-500 dark:placeholder:text-gray-500 focus:outline-none focus:ring-2 focus:ring-atomic-orange transition-all"
              />
            </div>
          )}

          {viewState !== 'FORGOT' && (
            <div className="relative group">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 dark:text-gray-400 group-focus-within:text-atomic-neon transition-colors" size={20} />
              <input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full pl-12 pr-4 py-3 rounded-xl bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/10 text-slate-900 dark:text-white placeholder:text-slate-500 dark:placeholder:text-gray-500 focus:outline-none focus:ring-2 focus:ring-atomic-neon transition-all"
              />
            </div>
          )}

          {error && (
            <div className="text-red-600 dark:text-red-400 text-xs text-center font-bold bg-red-500/10 py-2 rounded-lg border border-red-500/20">
              {error}
            </div>
          )}

           {successMsg && (
            <div className="text-green-600 dark:text-green-400 text-xs text-center font-bold bg-green-500/10 py-2 rounded-lg border border-green-500/20">
              {successMsg}
            </div>
          )}

          <button 
            type="submit"
            className="mt-2 bg-gradient-to-r from-blue-600 to-cyan-500 dark:from-atomic-blue dark:to-atomic-neon text-white dark:text-atomic-dark font-black py-3 rounded-xl uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-lg"
          >
            {viewState === 'REGISTER' ? 'Register' : viewState === 'FORGOT' ? 'Send Link' : 'Login'}
          </button>
        </form>

        <div className="mt-6 flex flex-col gap-2 text-center">
          {viewState === 'LOGIN' && (
             <>
                <button onClick={() => setViewState('REGISTER')} className="text-xs text-slate-600 dark:text-gray-400 hover:text-slate-900 dark:hover:text-white underline decoration-atomic-orange/50">Need an account? Register</button>
                <button onClick={() => setViewState('FORGOT')} className="text-xs text-slate-500 dark:text-gray-500 hover:text-slate-900 dark:hover:text-white">Forgot Password?</button>
             </>
          )}
          {(viewState === 'REGISTER' || viewState === 'FORGOT') && (
              <button onClick={() => setViewState('LOGIN')} className="text-xs text-slate-600 dark:text-gray-400 hover:text-slate-900 dark:hover:text-white underline decoration-atomic-blue/50">Back to Login</button>
          )}
        </div>
      </div>
    </div>
  );
};

// Settings Screen
const SettingsScreen: React.FC<{ user: User, onBack: () => void, onUpdateUser: (u: User) => void, onCustomize: () => void }> = ({ user, onBack, onUpdateUser, onCustomize }) => {
  const [activeTab, setActiveTab] = useState<'ACCOUNT' | 'AUDIO'>('ACCOUNT');
  const t = TRANSLATIONS[user.settings.language || Language.ENGLISH];

  // Account State
  const [newUsername, setNewUsername] = useState(user.username);
  const [newPassword, setNewPassword] = useState('');
  const [comms, setComms] = useState(user.settings.communications ?? true);
  const [message, setMessage] = useState<{type: 'success'|'error', text: string} | null>(null);

  // Audio State
  const [sfxVol, setSfxVol] = useState(user.settings.sfxVolume);
  const [musicVol, setMusicVol] = useState(user.settings.musicVolume);

  // 60 Days in ms
  const daysSinceChange = (Date.now() - user.lastUsernameChange) / (1000 * 60 * 60 * 24);
  const canChangeUsername = daysSinceChange > 60 || user.lastUsernameChange === 0; 
  const daysRemaining = Math.ceil(60 - daysSinceChange);

  const handleUpdateAccount = () => {
    setMessage(null);
    const updatedUser = { ...user };
    let changed = false;

    if (newUsername !== user.username) {
      if (newUsername.length < 3) {
        setMessage({type: 'error', text: 'Username too short.'});
        return;
      }
      updatedUser.username = newUsername;
      updatedUser.lastUsernameChange = Date.now();
      changed = true;
    }

    if (newPassword.length > 0) {
      if (newPassword.length < 3) {
        setMessage({type: 'error', text: 'Password too short.'});
        return;
      }
      updatedUser.password = newPassword;
      changed = true;
    }

    if (comms !== user.settings.communications) {
        updatedUser.settings.communications = comms;
        changed = true;
    }

    if (changed) {
      const result = StorageService.updateUserProfile(updatedUser);
      if (result.success) {
        onUpdateUser(updatedUser);
        setMessage({type: 'success', text: 'Profile updated successfully.'});
        setNewPassword('');
      } else {
        setMessage({type: 'error', text: result.message || 'Update failed.'});
      }
    } else {
        setMessage({type: 'success', text: 'No changes detected.'});
    }
  };

  const handleUpdateAudio = () => {
    const updatedUser = { 
      ...user, 
      settings: { 
        ...user.settings,
        sfxVolume: sfxVol, 
        musicVolume: musicVol 
      } 
    };
    const result = StorageService.updateUserProfile(updatedUser);
    if (result.success) {
      onUpdateUser(updatedUser);
      setMessage({type: 'success', text: 'Audio settings saved.'});
    }
  };

  const handleLanguageChange = (lang: Language) => {
      const updatedUser = { ...user, settings: { ...user.settings, language: lang } };
      StorageService.updateUserProfile(updatedUser);
      onUpdateUser(updatedUser);
  };

  return (
    <div className="flex flex-col h-full max-w-md mx-auto p-4 animate-in slide-in-from-bottom duration-300">
      <div className="flex items-center justify-between mb-6">
        <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 text-slate-600 dark:text-gray-300">
          <ArrowLeft />
        </button>
        <h2 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-wider">{t.settings}</h2>
        <div className="w-10"></div>
      </div>

      <div className="flex mb-6 bg-white/50 dark:bg-white/5 p-1 rounded-xl">
        <button 
          onClick={() => { setActiveTab('ACCOUNT'); setMessage(null); }}
          className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'ACCOUNT' ? 'bg-blue-600 text-white dark:bg-atomic-blue dark:text-atomic-dark shadow-lg' : 'text-slate-500 dark:text-gray-400 hover:text-slate-900 dark:hover:text-white'}`}
        >
          Account
        </button>
        <button 
