                 >
                    🇬🇧 English
                 </button>
                 <button 
                    onClick={() => handleLanguageChange(Language.PIRATE)}
                    className={`flex-1 py-2 rounded-lg border-2 ${user.settings.language === Language.PIRATE ? 'border-red-600 bg-red-100 dark:border-atomic-orange dark:bg-atomic-orange/20' : 'border-transparent bg-black/5 dark:bg-white/5'}`}
