function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'HOME' | 'GAME' | 'SCORES' | 'SETTINGS' | 'CUSTOMIZE'>('HOME');
  const [darkMode, setDarkMode] = useState(true);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.NORMAL);

  useEffect(() => {
    const saved = StorageService.getSession();
    if (saved) setUser(saved);
  }, []);

  const handleLogout = () => {
    StorageService.clearSession();
    setUser(null);
    setView('HOME');
  };

  const toggleTheme = () => {
    setDarkMode(!darkMode);
  };

  // Helper to get current translation based on user settings
  const t = user ? TRANSLATIONS[user.settings.language || Language.ENGLISH] : TRANSLATIONS[Language.ENGLISH];

  const handleScoreUpdate = (earnedCoins: number) => {
      if (user) {
          const updatedUser = { ...user, coins: user.coins + earnedCoins };
          StorageService.saveSession(updatedUser);
          StorageService.updateUserProfile(updatedUser); // Update in DB too
          setUser(updatedUser);
      }
  };

  return (
    <div className={`min-h-screen font-sans transition-colors duration-500 ${darkMode ? 'dark text-white' : 'text-slate-900'}`}>
      <AtomicBackground darkMode={darkMode} />

      {/* App Container */}
      <div className="relative z-10 container mx-auto h-screen flex flex-col">

        {/* Persistent Top Bar */}
         <div className="flex justify-between items-center p-4">
            {user && view === 'HOME' ? (
                <button onClick={handleLogout} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 text-slate-500 dark:text-gray-400">
                    <LogOut size={20} />
                </button>
            ) : <div className="w-10"></div>}

            <div className="flex gap-2">
               {user && view === 'HOME' && (
                   <button onClick={() => setView('SETTINGS')} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 text-slate-500 dark:text-gray-300">
                      <Settings size={20} />
                   </button>
               )}
               <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors bg-white/40 dark:bg-white/5 backdrop-blur-sm text-slate-900 dark:text-white">
                  {darkMode ? <Sun size={20} /> : <Moon size={20} />}
               </button>
            </div>
         </div>

        {/* View Routing */}
        <main className="flex-1 overflow-hidden">
            {!user ? (
                <LoginScreen onLogin={setUser} />
            ) : view === 'HOME' ? (
                <div className="flex flex-col items-center justify-center h-[75vh] gap-6 animate-in fade-in">
                    <Logo size="lg" />

                    <div className="flex flex-col items-center justify-center relative">
                         {/* Avatar Display */}
                         <div className="w-32 h-32 bg-white/40 dark:bg-black/30 rounded-full border-4 border-white/20 mb-4 overflow-hidden shadow-lg">
                            <Avatar config={user.avatar} language={user.settings.language} className="w-full h-full" />
                         </div>

                        <div className="text-center space-y-1 animate-in slide-in-from-bottom duration-700">
                            <p className="text-sm text-slate-500 dark:text-gray-400 uppercase tracking-widest">{t.welcome}</p>
                            <h1 className="text-3xl font-black text-slate-900 dark:text-white">{user.username}</h1>
                            <div className="flex items-center justify-center gap-1 text-yellow-500">
                                <Coins size={14} /> <span className="font-bold">{user.coins}</span> <span className="text-xs uppercase">{t.coins}</span>
                            </div>
                        </div>

                        <button 
                            onClick={() => setView('CUSTOMIZE')}
                            className="absolute -right-8 top-0 p-2 bg-white/20 dark:bg-white/5 rounded-full hover:bg-white/40 transition-colors"
                        >
                            <Shirt size={16} className="text-slate-600 dark:text-gray-300" />
                        </button>
                    </div>

                    <div className="flex flex-col gap-3 w-64">
                        {/* Difficulty Selector */}
                        <div className="flex justify-between bg-white/60 dark:bg-black/20 rounded-xl p-1 border border-black/5 dark:border-white/10">
                            {Object.values(Difficulty).map((d) => (
                                <button
                                    key={d}
                                    onClick={() => setDifficulty(d)}
                                    className={`
                                        flex-1 py-2 text-[10px] font-bold uppercase rounded-lg transition-all
                                        ${difficulty === d ? 'bg-blue-600 text-white dark:bg-atomic-blue dark:text-atomic-dark shadow-md' : 'text-slate-500 dark:text-gray-500 hover:text-slate-900 dark:hover:text-white'}
                                    `}
                                >
                                    {d.charAt(0)}
                                </button>
                            ))}
                        </div>
                        <div className="text-center text-[10px] text-slate-400 dark:text-gray-500 uppercase tracking-widest -mt-1 mb-1">
                            {difficulty} Mode
                        </div>

                        <button 
                            onClick={() => setView('GAME')}
                            className="group relative px-8 py-4 bg-blue-600 dark:bg-atomic-blue text-white dark:text-atomic-dark font-black text-xl rounded-xl shadow-lg dark:shadow-[0_0_20px_rgba(0,243,255,0.4)] hover:scale-105 transition-all overflow-hidden"
                        >
                            <span className="relative z-10 flex items-center justify-center gap-2">
                                <Play fill="currentColor" /> {t.play}
                            </span>
                            <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"/>
                        </button>

                        <button 
                            onClick={() => setView('SCORES')}
                            className="flex items-center justify-center gap-2 px-8 py-4 bg-white/60 dark:bg-white/10 backdrop-blur-md border border-black/5 dark:border-white/20 font-bold rounded-xl hover:bg-white/80 dark:hover:bg-white/20 text-slate-800 dark:text-white transition-all"
                        >
                            <Trophy className="text-orange-500 dark:text-atomic-orange" /> {t.leaderboard}
                        </button>
                    </div>
                </div>
            ) : view === 'GAME' ? (
                <GameScreen user={user} difficulty={difficulty} onExit={() => setView('HOME')} onScoreUpdate={handleScoreUpdate} />
            ) : view === 'SETTINGS' ? (
                <SettingsScreen user={user} onBack={() => setView('HOME')} onUpdateUser={setUser} onCustomize={() => setView('CUSTOMIZE')} />
            ) : view === 'CUSTOMIZE' ? (
                <CustomizeScreen user={user} onUpdateUser={setUser} onBack={() => setView('HOME')} />
            ) : (
                <LeaderboardScreen onBack={() => setView('HOME')} language={user.settings.language || Language.ENGLISH} />
            )}
        </main>
      </div>
    </div>
  );
}

const AtomSpinner = () => (
    <div className="relative w-16 h-16 animate-spin-slow">
        <div className="absolute inset-0 border-2 border-transparent border-t-blue-500 dark:border-t-atomic-blue rounded-full animate-spin"></div>
        <div className="absolute inset-2 border-2 border-transparent border-b-green-500 dark:border-b-atomic-neon rounded-full animate-pulse"></div>
    </div>
);

