import { LeaderboardEntry, User, Language } from "../types";

const CURRENT_USER_KEY = 'atomic_current_session';
const USERS_DB_KEY = 'atomic_users_db'; // Simulates a database
const SCORES_KEY = 'atomic_scores';

// --- Auth & User Management ---

const getUsersDB = (): User[] => {
  const data = localStorage.getItem(USERS_DB_KEY);
  return data ? JSON.parse(data) : [];
};

const saveUsersDB = (users: User[]) => {
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
};

export const registerUser = (username: string, email: string, password: string): { success: boolean; message?: string; user?: User } => {
  const users = getUsersDB();

  if (users.some(u => u.username.toLowerCase() === username.toLowerCase())) {
    return { success: false, message: "Username already taken." };
  }
  if (users.some(u => u.email.toLowerCase() === email.toLowerCase())) {
    return { success: false, message: "Email already registered." };
  }

  // Define default unlocked items (Basic items are free)
  const defaultInventory = [
    // Hair Styles
    'hair_bald', 'hair_short', 'hair_spiky', 'hair_long', 'hair_bob',
    // Hair Colors
    'hcolor_black', 'hcolor_brown', 'hcolor_blonde', 'hcolor_red', 'hcolor_gray',
    // Tops
    'top_tshirt', 'top_shirt', 'top_hoodie',
    // Top Colors
    'tcolor_blue', 'tcolor_red', 'tcolor_black', 'tcolor_white', 'tcolor_green',
    // Bottoms
    'bot_shorts', 'bot_pants', 'bot_skirt',
    // Bottom Colors
    'bcolor_jeans', 'bcolor_black', 'bcolor_khaki',
    // Beards
    'beard_none', 'beard_stubble', 'beard_full', 'beard_mustache',
    // Accessories (Basic glasses are free)
    'acc_none', 'acc_glasses' 
  ];

  const newUser: User = {
    id: crypto.randomUUID(),
    username,
    email,
    password, 
    lastUsernameChange: Date.now(),
    coins: 100, // Sign up bonus
    inventory: defaultInventory,
    avatar: {
        skinTone: '#f5d0b0',
        hairStyle: 'short',
        hairColor: '#4a3000',
        topType: 'tshirt',
        topColor: '#3b82f6',
        bottomType: 'shorts',
        bottomColor: '#1f2937',
        beard: 'none',
        accessory: 'none'
    },
    settings: {
      sfxVolume: 50,
      musicVolume: 50,
      communications: true,
      language: Language.ENGLISH
    }
  };

  users.push(newUser);
  saveUsersDB(users);
  saveSession(newUser);
  return { success: true, user: newUser };
};

export const loginUser = (username: string, password: string): { success: boolean; message?: string; user?: User } => {
  const users = getUsersDB();
  // Allow login by username OR email
  const user = users.find(u => 
    u.username.toLowerCase() === username.toLowerCase() || 
    u.email.toLowerCase() === username.toLowerCase()
  );

  if (!user || user.password !== password) {
    return { success: false, message: "Invalid credentials." };
  }

  saveSession(user);
  return { success: true, user };
};

export const requestPasswordReset = (email: string): { success: boolean; message: string } => {
  const users = getUsersDB();
  const user = users.find(u => u.email.toLowerCase() === email.toLowerCase());

  if (user) {
    return { success: true, message: `Reset link sent to ${email}` };
  } else {
    return { success: false, message: "Email not found." };
  }
};

export const updateUserProfile = (updatedUser: User): { success: boolean; message?: string } => {
  const users = getUsersDB();
  const index = users.findIndex(u => u.id === updatedUser.id);

  if (index === -1) return { success: false, message: "User not found." };

  // Check username uniqueness if changed
  if (users[index].username.toLowerCase() !== updatedUser.username.toLowerCase()) {
      const exists = users.some(u => u.id !== updatedUser.id && u.username.toLowerCase() === updatedUser.username.toLowerCase());
      if (exists) return { success: false, message: "Username taken." };
  }

  users[index] = updatedUser;
  saveUsersDB(users);
  saveSession(updatedUser);
  return { success: true };
};

// --- Session Management ---

export const saveSession = (user: User) => {
  localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
};

export const getSession = (): User | null => {
  const data = localStorage.getItem(CURRENT_USER_KEY);
  return data ? JSON.parse(data) : null;
};

export const clearSession = () => {
  localStorage.removeItem(CURRENT_USER_KEY);
};

// --- Scores ---

export const saveScore = (entry: LeaderboardEntry) => {
  const scores = getScores();
  scores.push(entry);
  scores.sort((a, b) => b.score - a.score);
  const topScores = scores.slice(0, 20);
  localStorage.setItem(SCORES_KEY, JSON.stringify(topScores));
};

export const getScores = (): LeaderboardEntry[] => {
  const data = localStorage.getItem(SCORES_KEY);
  return data ? JSON.parse(data) : [];
};

import React from 'react';
import { AvatarConfig, Language } from '../types';

interface AvatarProps {
  config: AvatarConfig;
  language?: Language;
  className?: string;
}

const Avatar: React.FC<AvatarProps> = ({ config, language = Language.ENGLISH, className }) => {
  const isPirate = language === Language.PIRATE;
  // Use a 24x24 grid for that retro/stardew look
  const GRID_SIZE = 24;

  // Helper to draw a rect on the pixel grid
  const Pixel = ({ x, y, w = 1, h = 1, color, opacity = 1 }: { x: number, y: number, w?: number, h?: number, color: string, opacity?: number }) => (
    <rect x={x} y={y} width={w} height={h} fill={color} fillOpacity={opacity} shapeRendering="crispEdges" />
  );

  return (
    <svg viewBox={`0 0 ${GRID_SIZE} ${GRID_SIZE}`} className={className} xmlns="http://www.w3.org/2000/svg">

      {/* --- BODY LAYER --- */}

      {/* Torso Base (Skin) */}
      <Pixel x={9} y={12} w={6} h={1} color={config.skinTone} /> {/* Neck */}

      {/* Pants/Bottoms */}
      {config.bottomType === 'pants' && (
        <>
            <Pixel x={9} y={18} w={6} h={2} color={config.bottomColor} />
            <Pixel x={9} y={20} w={2} h={4} color={config.bottomColor} />
            <Pixel x={13} y={20} w={2} h={4} color={config.bottomColor} />
        </>
      )}
      {config.bottomType === 'shorts' && (
        <>
            <Pixel x={9} y={18} w={6} h={2} color={config.bottomColor} />
            <Pixel x={9} y={20} w={2} h={1} color={config.bottomColor} />
            <Pixel x={13} y={20} w={2} h={1} color={config.bottomColor} />
            {/* Legs exposed */}
            <Pixel x={9} y={21} w={2} h={3} color={config.skinTone} />
            <Pixel x={13} y={21} w={2} h={3} color={config.skinTone} />
        </>
      )}
      {config.bottomType === 'skirt' && (
        <>
             <Pixel x={8} y={18} w={8} h={3} color={config.bottomColor} />
             <Pixel x={9} y={21} w={2} h={3} color={config.skinTone} />
             <Pixel x={13} y={21} w={2} h={3} color={config.skinTone} />
        </>
      )}

      {/* Shoes (Generic) */}
      <Pixel x={8} y={23} w={3} h={1} color="#333" />
      <Pixel x={13} y={23} w={3} h={1} color="#333" />

      {/* Shirt/Top */}
      <Pixel x={8} y={13} w={8} h={5} color={config.topColor} />
      {/* Arms (Sleeves vs Skin) */}
      {config.topType === 'tshirt' ? (
          <>
             <Pixel x={6} y={13} w={2} h={2} color={config.topColor} /> {/* Sleeves */}
             <Pixel x={6} y={15} w={2} h={4} color={config.skinTone} /> {/* Arms */}
             <Pixel x={16} y={13} w={2} h={2} color={config.topColor} />
             <Pixel x={16} y={15} w={2} h={4} color={config.skinTone} />
          </>
      ) : (
          <>
             <Pixel x={6} y={13} w={2} h={5} color={config.topColor} /> {/* Long Sleeves */}
             <Pixel x={6} y={18} w={2} h={1} color={config.skinTone} /> {/* Hands */}
             <Pixel x={16} y={13} w={2} h={5} color={config.topColor} />
             <Pixel x={16} y={18} w={2} h={1} color={config.skinTone} />
          </>
      )}

      {/* Suit Detail */}
      {config.topType === 'suit' && (
          <>
             <Pixel x={11} y={13} w={2} h={3} color="#FFF" />
             <Pixel x={11} y={14} w={2} h={2} color="#F00" opacity={0.5} /> {/* Tie */}
          </>
      )}

      {/* --- HEAD LAYER --- */}

      {/* Head Shape */}
      <Pixel x={7} y={4} w={10} h={9} color={config.skinTone} />

      {/* Eyes */}
      {!isPirate && config.accessory !== 'sunglasses' && (
         <>
            <Pixel x={9} y={8} w={2} h={2} color="#000" />
            <Pixel x={13} y={8} w={2} h={2} color="#000" />
            {/* Eye whites/shine */}
            <Pixel x={9} y={8} w={1} h={1} color="#FFF" opacity={0.6} />
            <Pixel x={13} y={8} w={1} h={1} color="#FFF" opacity={0.6} />
         </>
      )}

      {/* Pirate Eyepatch */}
      {(isPirate || config.accessory === 'eyepatch') && (
         <>
            <Pixel x={9} y={8} w={2} h={2} color="#000" /> {/* Left Eye */}
            <Pixel x={13} y={8} w={2} h={2} color="#000" /> {/* Patch */}
            <Pixel x={7} y={7} w={10} h={1} color="#000" opacity={0.8} /> {/* Strap */}
         </>
      )}

      {/* Sunglasses */}
      {config.accessory === 'sunglasses' && !isPirate && (
          <>
             <Pixel x={8} y={8} w={8} h={2} color="#111" />
             <Pixel x={8} y={8} w={1} h={1} color="#555" />
             <Pixel x={12} y={8} w={1} h={1} color="#555" />
          </>
      )}

      {/* Standard Glasses */}
      {config.accessory === 'glasses' && !isPirate && (
          <>
             <Pixel x={9} y={8} w={2} h={2} color="#000" opacity={0.2} />
             <Pixel x={13} y={8} w={2} h={2} color="#000" opacity={0.2} />
             <Pixel x={11} y={9} w={2} h={1} color="#333" />
             <rect x={9} y={8} width={2} height={2} fill="none" stroke="#333" strokeWidth={0.5} shapeRendering="crispEdges" />
             <rect x={13} y={8} width={2} height={2} fill="none" stroke="#333" strokeWidth={0.5} shapeRendering="crispEdges" />
          </>
      )}

      {/* Beard */}
      {config.beard === 'stubble' && (
          <Pixel x={8} y={10} w={8} h={3} color="#000" opacity={0.1} />
      )}
      {config.beard === 'full' && (
          <>
            <Pixel x={7} y={10} w={10} h={3} color={config.hairColor} />
            <Pixel x={8} y={13} w={8} h={1} color={config.hairColor} />
          </>
      )}
      {config.beard === 'mustache' && (
          <Pixel x={9} y={10} w={6} h={1} color={config.hairColor} />
      )}

      {/* Hair */}
      {config.hairStyle !== 'bald' && (
        <>
            {/* Sideburns/Base */}
            <Pixel x={7} y={5} w={1} h={4} color={config.hairColor} />
            <Pixel x={16} y={5} w={1} h={4} color={config.hairColor} />

            {/* Top */}
            <Pixel x={7} y={3} w={10} h={2} color={config.hairColor} />

            {/* Styles */}
            {config.hairStyle === 'short' && (
                <Pixel x={8} y={2} w={8} h={1} color={config.hairColor} />
            )}
            {config.hairStyle === 'bob' && (
                 <>
                    <Pixel x={6} y={4} w={2} h={6} color={config.hairColor} />
                    <Pixel x={16} y={4} w={2} h={6} color={config.hairColor} />
                 </>
            )}
            {config.hairStyle === 'long' && (
                 <>
                    <Pixel x={6} y={4} w={2} h={10} color={config.hairColor} />
                    <Pixel x={16} y={4} w={2} h={10} color={config.hairColor} />
                 </>
            )}
            {config.hairStyle === 'spiky' && (
                 <>
                    <Pixel x={8} y={1} w={2} h={2} color={config.hairColor} />
                    <Pixel x={11} y={0} w={2} h={3} color={config.hairColor} />
                    <Pixel x={14} y={1} w={2} h={2} color={config.hairColor} />
                 </>
            )}
        </>
      )}

      {/* Hat */}
      {config.accessory === 'hat' && (
          <>
            <Pixel x={6} y={3} w={12} h={1} color="#222" />
            <Pixel x={8} y={1} w={8} h={2} color="#222" />
          </>
      )}
      {config.accessory === 'crown' && (
          <>
             <Pixel x={7} y={1} w={10} h={3} color="#FFD700" />
             <Pixel x={7} y={1} w={1} h={1} color="#000" opacity={0} />
             {/* Gems */}
             <Pixel x={9} y={2} w={1} h={1} color="#F00" />
             <Pixel x={12} y={2} w={1} h={1} color="#0F0" />
             <Pixel x={15} y={2} w={1} h={1} color="#00F" />
          </>
      )}

      {/* Pirate Parrot (Shoulder) */}
      {isPirate && (
          <g>
              <Pixel x={16} y={12} w={3} h={1} color="red" /> {/* Body */}
              <Pixel x={17} y={11} w={1} h={1} color="red" /> {/* Head */}
              <Pixel x={18} y={11} w={1} h={1} color="yellow" /> {/* Beak */}
              <Pixel x={18} y={13} w={1} h={2} color="blue" /> {/* Tail */}
          </g>
      )}

    </svg>
  );
};

