import React, { useMemo } from 'react';
import { AvatarConfig, Language } from '../types';

interface AvatarProps {
  config: AvatarConfig;
  language?: Language;
  className?: string;
}

const Avatar: React.FC<AvatarProps> = ({ config, language = Language.ENGLISH, className }) => {
  const isPirate = language === Language.PIRATE;
  const uniqueId = useMemo(() => Math.random().toString(36).substr(2, 9), []);

  // --- Color Helpers ---
  // Simple darkening/lightening for gradients based on the base hex
  const adjustColor = (hex: string, percent: number) => {
    // Basic hex manipulation for demo purposes
    // In a real app, use a library like tinycolor2
    if (!hex.startsWith('#')) return hex;
    let r = parseInt(hex.substring(1, 3), 16);
    let g = parseInt(hex.substring(3, 5), 16);
    let b = parseInt(hex.substring(5, 7), 16);

    r = Math.floor(r * (1 + percent / 100));
    g = Math.floor(g * (1 + percent / 100));
    b = Math.floor(b * (1 + percent / 100));

    r = r < 255 ? r : 255;
    g = g < 255 ? g : 255;
    b = b < 255 ? b : 255;

    const rr = (r.toString(16).length === 1) ? "0" + r.toString(16) : r.toString(16);
    const gg = (g.toString(16).length === 1) ? "0" + g.toString(16) : g.toString(16);
    const bb = (b.toString(16).length === 1) ? "0" + b.toString(16) : b.toString(16);

    return "#" + rr + gg + bb;
  };

  const skinDark = adjustColor(config.skinTone, -20);
  const skinLight = adjustColor(config.skinTone, 10);
  const hairDark = adjustColor(config.hairColor, -30);
  const hairLight = adjustColor(config.hairColor, 30);
  const topDark = adjustColor(config.topColor, -20);

  return (
    <svg viewBox="0 0 200 200" className={className} xmlns="http://www.w3.org/2000/svg">
      <defs>
        {/* Skin Gradient - Gives spherical 3D look to head */}
        <radialGradient id={`skinGrad-${uniqueId}`} cx="40%" cy="30%" r="70%">
          <stop offset="0%" stopColor={skinLight} />
          <stop offset="100%" stopColor={skinDark} />
        </radialGradient>

        {/* Hair Gradient - Adds shine/volume */}
        <linearGradient id={`hairGrad-${uniqueId}`} x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor={hairLight} />
          <stop offset="50%" stopColor={config.hairColor} />
          <stop offset="100%" stopColor={hairDark} />
        </linearGradient>

        {/* Cloth Gradient */}
        <linearGradient id={`clothGrad-${uniqueId}`} x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor={topDark} />
          <stop offset="50%" stopColor={config.topColor} />
          <stop offset="100%" stopColor={topDark} />
        </linearGradient>

        {/* Drop Shadow Filter */}
        <filter id={`shadow-${uniqueId}`} x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur in="SourceAlpha" stdDeviation="2" />
          <feOffset dx="0" dy="2" result="offsetblur" />
          <feComponentTransfer>
            <feFuncA type="linear" slope="0.3" />
          </feComponentTransfer>
          <feMerge>
            <feMergeNode />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      {/* --- BACKGROUND / BACK HAIR --- */}
      {config.hairStyle === 'long' && (
        <path 
          d="M60,80 Q50,150 55,180 L145,180 Q150,150 140,80" 
          fill={hairDark} 
        />
      )}
      {config.hairStyle === 'bob' && (
        <path 
          d="M60,90 Q50,140 65,150 L135,150 Q150,140 140,90" 
          fill={hairDark} 
        />
      )}

      {/* --- BODY --- */}
      {/* Neck */}
      <rect x="85" y="130" width="30" height="40" fill={skinDark} />

      {/* Shoulders/Top */}
      <path 
        d="M50,160 Q100,150 150,160 L160,200 L40,200 Z" 
        fill={`url(#clothGrad-${uniqueId})`} 
        filter={`url(#shadow-${uniqueId})`}
      />

      {/* Collar details */}
      {config.topType === 'suit' && (
         <path d="M100,160 L100,200 M85,160 L100,180 L115,160" stroke="#000" strokeOpacity="0.2" strokeWidth="2" fill="none"/>
      )}
      {config.topType === 'hoodie' && (
         <path d="M70,160 Q100,200 130,160" stroke={topDark} strokeWidth="5" fill="none" />
      )}

      {/* --- HEAD --- */}
      {/* Face Shape (Jawline slightly squared but rounded for 3D cartoon look) */}
      <path 
        d="M65,80 Q65,150 100,150 Q135,150 135,80 Q135,30 100,30 Q65,30 65,80" 
        fill={`url(#skinGrad-${uniqueId})`}
      />

      {/* Ears */}
      <circle cx="62" cy="95" r="8" fill={skinDark} />
      <circle cx="138" cy="95" r="8" fill={skinDark} />

      {/* --- FACIAL FEATURES --- */}

      {/* Mouth */}
      <path d="M90,125 Q100,130 110,125" stroke="#aa7755" strokeWidth="3" strokeLinecap="round" fill="none" opacity="0.6"/>

      {/* Nose */}
      <path d="M100,105 Q95,115 100,115 Q105,115 100,105" fill="#c68c60" opacity="0.3" />

      {/* Eyes */}
      {/* Whites */}
      <ellipse cx="82" cy="90" rx="10" ry="8" fill="#FFF" />
      <ellipse cx="118" cy="90" rx="10" ry="8" fill="#FFF" />

      {/* Iris */}
      {(!isPirate && config.accessory !== 'sunglasses') && (
        <>
            <circle cx="82" cy="90" r="4" fill="#333" />
            <circle cx="118" cy="90" r="4" fill="#333" />
            {/* Reflection */}
            <circle cx="84" cy="88" r="1.5" fill="#FFF" opacity="0.8" />
            <circle cx="120" cy="88" r="1.5" fill="#FFF" opacity="0.8" />
        </>
      )}

      {/* Eyebrows */}
      <path d="M72,80 Q82,75 92,80" stroke={config.hairColor} strokeWidth="3" strokeLinecap="round" fill="none" />
      <path d="M108,80 Q118,75 128,80" stroke={config.hairColor} strokeWidth="3" strokeLinecap="round" fill="none" />

      {/* Pirate Eyepatch */}
      {(isPirate || config.accessory === 'eyepatch') && (
          <g>
            <circle cx="82" cy="90" r="11" fill="#000" />
            <path d="M82,90 L138,50" stroke="#000" strokeWidth="2" />
          </g>
      )}

      {/* Sunglasses */}
      {config.accessory === 'sunglasses' && !isPirate && (
          <g filter={`url(#shadow-${uniqueId})`}>
             <path d="M65,85 Q82,85 82,95 Q82,105 70,105 Q60,105 60,95 Z" fill="#222" stroke="#000" strokeWidth="2" />
             <path d="M135,85 Q118,85 118,95 Q118,105 130,105 Q140,105 140,95 Z" fill="#222" stroke="#000" strokeWidth="2" />
             <line x1="82" y1="90" x2="118" y2="90" stroke="#000" strokeWidth="3" />
          </g>
      )}

      {/* Regular Glasses */}
      {config.accessory === 'glasses' && !isPirate && (
           <g filter={`url(#shadow-${uniqueId})`}>
             <circle cx="82" cy="90" r="12" stroke="#333" strokeWidth="3" fill="rgba(255,255,255,0.1)" />
             <circle cx="118" cy="90" r="12" stroke="#333" strokeWidth="3" fill="rgba(255,255,255,0.1)" />
             <line x1="94" y1="90" x2="106" y2="90" stroke="#333" strokeWidth="3" />
           </g>
      )}

      {/* Beard */}
      {config.beard === 'full' && (
        <path d="M65,95 Q65,150 100,150 Q135,150 135,95 L135,110 Q100,160 65,110 Z" fill={config.hairColor} opacity="0.9" />
      )}
      {config.beard === 'stubble' && (
        <path d="M65,100 Q100,160 135,100" stroke={config.hairColor} strokeWidth="15" strokeOpacity="0.1" fill="none" strokeLinecap="round" />
      )}
      {config.beard === 'mustache' && (
        <path d="M85,115 Q100,110 115,115 Q100,125 85,115" fill={config.hairColor} />
      )}

      {/* --- FRONT HAIR --- */}

      {config.hairStyle === 'short' && (
          <path 
            d="M60,90 Q60,30 100,25 Q140,30 140,80 L140,60 Q100,10 60,60 Z" 
            fill={`url(#hairGrad-${uniqueId})`}
            filter={`url(#shadow-${uniqueId})`}
          />
      )}

      {config.hairStyle === 'spiky' && (
           <path 
             d="M60,80 Q70,20 100,20 Q120,10 140,80 L140,60 Q120,40 100,50 Q80,40 60,60 Z" 
             fill={`url(#hairGrad-${uniqueId})`}
             filter={`url(#shadow-${uniqueId})`}
           />
      )}

      {config.hairStyle === 'bob' && (
          <path 
            d="M60,50 Q100,10 140,50 L145,130 Q145,140 130,120 L130,60 Q100,40 70,60 L70,120 Q55,140 55,130 Z" 
            fill={`url(#hairGrad-${uniqueId})`}
            filter={`url(#shadow-${uniqueId})`}
          />
      )}

      {config.hairStyle === 'long' && (
          <path 
             d="M60,60 Q100,10 140,60 L150,160 Q150,180 130,160 L130,80 Q100,50 70,80 L70,160 Q50,180 50,160 Z"
             fill={`url(#hairGrad-${uniqueId})`}
             filter={`url(#shadow-${uniqueId})`}
          />
      )}

      {/* Hat (On top of hair) */}
      {config.accessory === 'hat' && (
        <g filter={`url(#shadow-${uniqueId})`}>
           <ellipse cx="100" cy="55" rx="50" ry="25" fill="#222" />
           <path d="M70,55 L70,25 Q100,10 130,25 L130,55 Z" fill="#333" />
           <rect x="70" y="50" width="60" height="5" fill="#555" />
        </g>
      )}

      {config.accessory === 'crown' && (
         <g filter={`url(#shadow-${uniqueId})`}>
            <path d="M70,60 L70,30 L85,50 L100,20 L115,50 L130,30 L130,60 Z" fill="#FFD700" stroke="#DAA520" strokeWidth="2"/>
            <circle cx="100" cy="50" r="3" fill="red" />
            <circle cx="85" cy="45" r="2" fill="blue" />
            <circle cx="115" cy="45" r="2" fill="green" />
         </g>
      )}

      {/* Pirate Parrot (Shoulder) - Updated Style */}
      {isPirate && (
          <g transform="translate(135, 135) rotate(-10)">
              <path d="M10,20 Q5,0 20,5 Q30,10 30,30 L25,50 L10,50 Z" fill="#D00" />
              <circle cx="20" cy="10" r="4" fill="#FFF" />
              <circle cx="21" cy="10" r="1.5" fill="#000" />
              <path d="M22,10 L30,12 L25,18 Z" fill="#FB1" />
              <path d="M5,30 L15,30 L10,50 Z" fill="#00F" />
