export default App;

import React, { useMemo } from 'react';
import { AvatarConfig, Language } from '../types';

interface AvatarProps {
  config: AvatarConfig;
  language?: Language;
  className?: string;
}

const Avatar: React.FC<AvatarProps> = ({ config, language = Language.ENGLISH, className }) => {
  const isPirate = language === Language.PIRATE;
  const uniqueId = useMemo(() => Math.random().toString(36).substr(2, 9), []);

  // Helper to adjust hex colors for shading (darken/lighten)
  const adjustColor = (hex: string, amt: number) => {
    let usePound = false;
    if (hex[0] === "#") {
      hex = hex.slice(1);
      usePound = true;
    }
    let num = parseInt(hex, 16);
    let r = (num >> 16) + amt;
    if (r > 255) r = 255;
    else if (r < 0) r = 0;
    let b = ((num >> 8) & 0x00FF) + amt;
    if (b > 255) b = 255;
    else if (b < 0) b = 0;
    let g = (num & 0x0000FF) + amt;
    if (g > 255) g = 255;
    else if (g < 0) g = 0;
    return (usePound ? "#" : "") + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
  };

  const skinBase = config.skinTone;
  const skinShadow = adjustColor(skinBase, -40);
  const skinHighlight = adjustColor(skinBase, 20);

  const hairBase = config.hairColor;
  const hairShadow = adjustColor(hairBase, -60);
  const hairHighlight = adjustColor(hairBase, 40);

  const topBase = config.topColor;

  return (
    <svg viewBox="0 0 200 200" className={className} xmlns="http://www.w3.org/2000/svg" shapeRendering="geometricPrecision">
      <defs>
        {/* Soft Skin Gradient - Simulates Subsurface Scattering */}
        <radialGradient id={`skinGrad-${uniqueId}`} cx="35%" cy="35%" r="60%">
          <stop offset="0%" stopColor={skinHighlight} />
          <stop offset="100%" stopColor={skinBase} />
        </radialGradient>

        {/* Deep Skin Shadow for edges (Ambient Occlusion) */}
        <radialGradient id={`skinShadowGrad-${uniqueId}`} cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
            <stop offset="80%" stopColor={skinBase} stopOpacity="0" />
            <stop offset="100%" stopColor={skinShadow} stopOpacity="0.5" />
        </radialGradient>

        {/* Hair Gradient (Vertical sheen for volume) */}
        <linearGradient id={`hairGrad-${uniqueId}`} x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor={hairHighlight} />
          <stop offset="30%" stopColor={hairBase} />
          <stop offset="100%" stopColor={hairShadow} />
        </linearGradient>

        {/* Glossy Eye Gradient */}
        <radialGradient id={`eyeGrad-${uniqueId}`} cx="50%" cy="50%" r="50%">
            <stop offset="80%" stopColor="#3e2723" />
            <stop offset="100%" stopColor="#000000" />
        </radialGradient>

        {/* Soft Shadow for Hair depth */}
        <filter id={`softShadow-${uniqueId}`} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur in="SourceAlpha" stdDeviation="2" />
          <feOffset dx="0" dy="3" result="offsetblur" />
          <feComponentTransfer>
            <feFuncA type="linear" slope="0.3" />
          </feComponentTransfer>
          <feMerge>
            <feMergeNode />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      {/* --- BACK HAIR (for volume) --- */}
      {(config.hairStyle === 'long' || config.hairStyle === 'bob') && (
         <path 
           d="M60,100 C50,140 50,170 60,180 L140,180 C150,170 150,140 140,100" 
           fill={hairShadow} 
         />
      )}

      {/* --- NECK & SHOULDERS --- */}
      <path d="M82,140 L82,170 L118,170 L118,140" fill={skinShadow} />

      {/* Clothing */}
      <path 
        d="M50,175 C80,170 120,170 150,175 L160,200 L40,200 Z" 
        fill={topBase} 
      />
      {config.topType === 'suit' && (
          <path d="M100,175 L100,200 M90,175 L100,190 L110,175" stroke="rgba(0,0,0,0.3)" strokeWidth="1" fill="none"/>
      )}

      {/* --- HEAD --- */}
      <g>
        {/* Face Shape - Softened Square/Oval mix */}
        <path 
            d="M55,90 C55,145 70,165 100,165 C130,165 145,145 145,90 C145,40 125,30 100,30 C75,30 55,40 55,90" 
            fill={`url(#skinGrad-${uniqueId})`}
        />
        {/* Edge Shadow Overlay */}
        <path 
            d="M55,90 C55,145 70,165 100,165 C130,165 145,145 145,90 C145,40 125,30 100,30 C75,30 55,40 55,90" 
            fill={`url(#skinShadowGrad-${uniqueId})`}
        />

        {/* Ears */}
        <path d="M55,100 C50,95 48,100 48,110 C48,120 50,125 55,120" fill={skinBase} />
        <path d="M145,100 C150,95 152,100 152,110 C152,120 150,125 145,120" fill={skinBase} />
      </g>

      {/* --- FEATURES --- */}

      {/* Eyes - Large, cute style */}
      <g transform="translate(0, 10)">
         {/* Left Eye */}
         <g transform="translate(76, 100)">
             <ellipse rx="10" ry="8" fill="#FFF" />
             {(!isPirate && config.accessory !== 'sunglasses') && (
                <>
                 <circle r="5" fill={`url(#eyeGrad-${uniqueId})`} />
                 <circle cx="2" cy="-2" r="2" fill="#FFF" opacity="0.9" />
                </>
             )}
         </g>
         {/* Right Eye */}
         <g transform="translate(124, 100)">
             <ellipse rx="10" ry="8" fill="#FFF" />
             {(!isPirate && config.accessory !== 'sunglasses') && (
                <>
                 <circle r="5" fill={`url(#eyeGrad-${uniqueId})`} />
                 <circle cx="2" cy="-2" r="2" fill="#FFF" opacity="0.9" />
                </>
             )}
         </g>
      </g>

      {/* Eyebrows - Expressive */}
      <path d="M66,95 Q76,90 86,95" stroke={hairShadow} strokeWidth="3" fill="none" strokeLinecap="round" />
      <path d="M114,95 Q124,90 134,95" stroke={hairShadow} strokeWidth="3" fill="none" strokeLinecap="round" />

      {/* Nose - Subtle */}
      <path d="M100,118 Q96,125 100,128 Q104,125 100,118" fill={skinShadow} opacity="0.5" />

      {/* Mouth - Soft Smile */}
      <path d="M90,145 Q100,150 110,145" stroke="#a1887f" strokeWidth="2.5" strokeLinecap="round" fill="none" />

      {/* Glasses - Thin Dark Frames */}
      {config.accessory === 'glasses' && !isPirate && (
          <g transform="translate(0, 10)" opacity="0.9">
             <circle cx="76" cy="100" r="14" stroke="#222" strokeWidth="2" fill="rgba(255,255,255,0.1)" />
             <circle cx="124" cy="100" r="14" stroke="#222" strokeWidth="2" fill="rgba(255,255,255,0.1)" />
             <path d="M90,100 Q100,92 110,100" stroke="#222" strokeWidth="2" fill="none" />
             <line x1="62" y1="100" x2="52" y2="95" stroke="#222" strokeWidth="2" />
             <line x1="138" y1="100" x2="148" y2="95" stroke="#222" strokeWidth="2" />
          </g>
      )}

      {config.accessory === 'sunglasses' && !isPirate && (
         <g transform="translate(0, 10)">
            <path d="M60,92 Q78,92 78,102 Q78,112 68,112 Q58,112 58,102 Z" fill="#111" stroke="#000" strokeWidth="1" transform="scale(1.3) translate(-14, -8)" />
            <path d="M137,92 Q122,92 122,102 Q122,112 132,112 Q142,112 142,102 Z" fill="#111" stroke="#000" strokeWidth="1" transform="scale(1.3) translate(-9, -8)" />
            <line x1="78" y1="95" x2="122" y2="95" stroke="#111" strokeWidth="3" />
         </g>
      )}

      {/* Pirate Eyepatch */}
      {(isPirate || config.accessory === 'eyepatch') && (
         <g transform="translate(0, 10)">
            <circle cx="76" cy="100" r="13" fill="#111" />
            <path d="M76,100 L145,60" stroke="#111" strokeWidth="2" />
         </g>
      )}


      {/* --- HAIR (FRONT) --- */}
      <g filter={`url(#softShadow-${uniqueId})`}>
        {config.hairStyle === 'short' && (
          // Side part, swept (Reference Image 1)
          <path 
            d="M50,80 C50,30 90,20 110,20 C140,20 155,50 150,80 C145,100 145,80 145,60 C140,40 120,30 100,40 C80,30 50,40 50,80 Z" 
            fill={`url(#hairGrad-${uniqueId})`}
          />
        )}

        {config.hairStyle === 'spiky' && (
          // Textured/Undercut (Reference Image 3)
          <path 
            d="M55,90 C60,40 80,30 100,30 C130,20 150,50 145,80 L145,60 C130,20 100,20 70,60 Z" 
            fill={`url(#hairGrad-${uniqueId})`}
          />
        )}

        {config.hairStyle === 'long' && (
           // Big Voluminous Side Sweep (Reference Image 2)
           <path 
             d="M55,180 C50,150 50,100 60,60 C80,20 130,20 150,70 L155,180 L135,180 L135,100 C135,50 100,40 80,70 L75,180 Z"
             fill={`url(#hairGrad-${uniqueId})`}
           />
        )}

        {config.hairStyle === 'bob' && (
           // Rounded Bob (Reference Image 4)
           <path 
             d="M55,140 C55,100 60,60 80,40 C110,20 140,40 145,100 L145,140 C145,150 130,130 130,100 C130,50 100,40 80,60 L75,140 Z"
             fill={`url(#hairGrad-${uniqueId})`}
           />
        )}

        {/* Specular Hair Highlight - Crucial for 3D look */}
        {config.hairStyle !== 'bald' && (
             <path 
               d="M70,45 Q100,35 130,45" 
               stroke="rgba(255,255,255,0.3)" 
               strokeWidth="6" 
               fill="none" 
               strokeLinecap="round"
               filter="blur(1px)"
             />
        )}
      </g>

      {/* Hat (On top of hair) */}
      {config.accessory === 'hat' && (
        <g filter={`url(#softShadow-${uniqueId})`}>
           <ellipse cx="100" cy="55" rx="55" ry="25" fill="#222" />
           <path d="M70,55 L70,25 Q100,10 130,25 L130,55 Z" fill="#333" />
           <rect x="70" y="50" width="60" height="5" fill="#555" />
        </g>
      )}

       {/* Pirate Parrot (Shoulder) */}
      {isPirate && (
          <g transform="translate(135, 135) rotate(-10)">
              <path d="M10,20 Q5,0 20,5 Q30,10 30,30 L25,50 L10,50 Z" fill="#D00" />
              <circle cx="20" cy="10" r="4" fill="#FFF" />
              <circle cx="21" cy="10" r="1.5" fill="#000" />
              <path d="M22,10 L30,12 L25,18 Z" fill="#FB1" />
              <path d="M5,30 L15,30 L10,50 Z" fill="#00F" />
          </g>
      )}

    </svg>
  );
};

