        <radialGradient id={`skinShadowGrad-${uniqueId}`} cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
            <stop offset="80%" stopColor={skinBase} stopOpacity="0" />
            <stop offset="100%" stopColor={skinShadow} stopOpacity="0.5" />
        </radialGradient>

        {/* Hair Gradient */}
        <linearGradient id={`hairGrad-${uniqueId}`} x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor={hairHighlight} />
          <stop offset="30%" stopColor={hairBase} />
          <stop offset="100%" stopColor={hairShadow} />
        </linearGradient>

        {/* Glossy Eye Gradient */}
        <radialGradient id={`eyeGrad-${uniqueId}`} cx="50%" cy="50%" r="50%">
            <stop offset="80%" stopColor="#3e2723" />
            <stop offset="100%" stopColor="#000000" />
        </radialGradient>

        {/* Cloth Gradients */}
        <linearGradient id={`topGrad-${uniqueId}`} x1="0%" y1="0%" x2="100%" y2="0%">
             <stop offset="0%" stopColor={topShadow} />
             <stop offset="50%" stopColor={topBase} />
             <stop offset="100%" stopColor={topShadow} />
        </linearGradient>

         <linearGradient id={`botGrad-${uniqueId}`} x1="0%" y1="0%" x2="100%" y2="0%">
             <stop offset="0%" stopColor={botShadow} />
             <stop offset="50%" stopColor={botBase} />
             <stop offset="100%" stopColor={botShadow} />
        </linearGradient>

        {/* Filters */}
        <filter id={`softShadow-${uniqueId}`} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur in="SourceAlpha" stdDeviation="2" />
          <feOffset dx="0" dy="3" result="offsetblur" />
          <feComponentTransfer>
            <feFuncA type="linear" slope="0.3" />
          </feComponentTransfer>
          <feMerge>
            <feMergeNode />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      {/* --- BACK HAIR --- */}
      {(config.hairStyle === 'long' || config.hairStyle === 'bob') && (
         <path 
           d="M60,100 C50,140 50,170 60,180 L140,180 C150,170 150,140 140,100" 
           fill={hairShadow} 
         />
      )}

      {/* --- LEGS / BOTTOMS --- */}
