                 <rect x="115" y="0" width="20" height="140" fill={skinShadow} />
                 {/* Skirt Fabric */}
                 <path d="M60,0 L40,80 L160,80 L140,0 Z" fill={`url(#botGrad-${uniqueId})`} />
