          {/* Shoes */}
          <path d="M55,140 L95,140 L95,150 C95,160 85,165 55,165 L55,140" fill="#111" />
          <path d="M105,140 L145,140 L145,165 C115,165 105,160 105,150 L105,140" fill="#111" />
