        )}
        {config.topType === 'suit' && (
             <g>
                 <path d="M100,0 L100,110" stroke="none" />
                 <path d="M100,0 L85,30 L100,60 L115,30 Z" fill="#900" /> {/* Tie */}
                 <path d="M85,0 L100,60 L115,0" fill="none" stroke="#FFF" strokeWidth="1"/> 
             </g>
        )}
      </g>

      {/* --- HEAD (Translated slightly) --- */}
      <g transform="translate(0, 0)">
