        {config.hairStyle === 'long' && (
           <path d="M55,180 C50,150 50,100 60,60 C80,20 130,20 150,70 L155,180 L135,180 L135,100 C135,50 100,40 80,70 L75,180 Z" fill={`url(#hairGrad-${uniqueId})`} />
        )}
        {config.hairStyle === 'bob' && (
           <path d="M55,140 C55,100 60,60 80,40 C110,20 140,40 145,100 L145,140 C145,150 130,130 130,100 C130,50 100,40 80,60 L75,140 Z" fill={`url(#hairGrad-${uniqueId})`} />
        )}
        {config.hairStyle !== 'bald' && (
             <path d="M70,45 Q100,35 130,45" stroke="rgba(255,255,255,0.3)" strokeWidth="6" fill="none" strokeLinecap="round" filter="blur(1px)" />
        )}
      </g>

      {/* Hat */}
      {config.accessory === 'hat' && (
        <g filter={`url(#softShadow-${uniqueId})`}>
           <ellipse cx="100" cy="55" rx="55" ry="25" fill="#222" />
           <path d="M70,55 L70,25 Q100,10 130,25 L130,55 Z" fill="#333" />
           <rect x="70" y="50" width="60" height="5" fill="#555" />
        </g>
      )}

       {/* Crown */}
       {config.accessory === 'crown' && (
         <g filter={`url(#softShadow-${uniqueId})`}>
            <path d="M70,60 L70,30 L85,50 L100,20 L115,50 L130,30 L130,60 Z" fill="#FFD700" stroke="#DAA520" strokeWidth="2"/>
         </g>
      )}

       {/* Parrot */}
      {isPirate && (
          <g transform="translate(135, 135) rotate(-10)">
              <path d="M10,20 Q5,0 20,5 Q30,10 30,30 L25,50 L10,50 Z" fill="#D00" />
              <circle cx="20" cy="10" r="4" fill="#FFF" />
              <circle cx="21" cy="10" r="1.5" fill="#000" />
          </g>
      )}

    </svg>
  );
};

