// Mini SVG Icons for Customization Items
const ItemPreview: React.FC<{ category: keyof AvatarConfig, value: string }> = ({ category, value }) => {
    if (value.startsWith('#')) {
         return <div className="w-8 h-8 rounded-full border border-black/20 shadow-sm" style={{ backgroundColor: value }} />;
    }

    const IconWrapper: React.FC<{children: React.ReactNode}> = ({children}) => (
        <svg viewBox="0 0 40 40" className="w-8 h-8 fill-slate-500 dark:fill-gray-400">
            {children}
        </svg>
    );

    // Hair
    if (category === 'hairStyle') {
        if (value === 'bald') return <IconWrapper><circle cx="20" cy="20" r="12" opacity="0.5"/></IconWrapper>;
        if (value === 'short') return <IconWrapper><path d="M10,20 Q20,5 30,20 L30,15 Q20,0 10,15 Z" /></IconWrapper>;
        if (value === 'spiky') return <IconWrapper><path d="M10,20 L15,10 L20,20 L25,10 L30,20 Z" /></IconWrapper>;
        if (value === 'long') return <IconWrapper><path d="M10,10 Q20,0 30,10 L32,30 L28,30 L28,20 Q20,15 12,20 L12,30 L8,30 Z" /></IconWrapper>;
        if (value === 'bob') return <IconWrapper><path d="M10,15 Q20,5 30,15 L32,25 Q20,20 8,25 Z" /></IconWrapper>;
    }

    // Top
    if (category === 'topType') {
        if (value === 'tshirt') return <IconWrapper><path d="M10,10 L30,10 L35,20 L30,22 L28,15 L28,30 L12,30 L12,15 L10,22 L5,20 Z" /></IconWrapper>;
        if (value === 'shirt') return <IconWrapper><path d="M12,10 L28,10 L28,30 L12,30 Z" /><line x1="20" y1="10" x2="20" y2="30" stroke="currentColor" strokeWidth="1"/></IconWrapper>;
        if (value === 'hoodie') return <IconWrapper><path d="M12,10 Q20,20 28,10 L28,30 L12,30 Z" /></IconWrapper>;
        if (value === 'suit') return <IconWrapper><path d="M12,10 L20,20 L28,10 L28,30 L12,30 Z" /><path d="M18,10 L20,25 L22,10" fill="currentColor"/></IconWrapper>;
    }

    // Bottom
    if (category === 'bottomType') {
        if (value === 'shorts') return <IconWrapper><path d="M12,10 L28,10 L28,25 L20,18 L12,25 Z" /></IconWrapper>;
        if (value === 'pants') return <IconWrapper><path d="M12,10 L28,10 L28,35 L20,25 L12,35 Z" /></IconWrapper>;
        if (value === 'skirt') return <IconWrapper><path d="M15,10 L25,10 L30,30 L10,30 Z" /></IconWrapper>;
    }

    // Beard
    if (category === 'beard') {
        if (value === 'none') return <IconWrapper><circle cx="20" cy="20" r="10" stroke="currentColor" fill="none" /></IconWrapper>;
        if (value === 'stubble') return <IconWrapper><circle cx="20" cy="20" r="10" stroke="currentColor" strokeDasharray="2" fill="none" /></IconWrapper>;
        if (value === 'mustache') return <IconWrapper><path d="M15,22 Q20,18 25,22" stroke="currentColor" strokeWidth="3" fill="none"/></IconWrapper>;
        if (value === 'full') return <IconWrapper><path d="M12,20 Q20,35 28,20" stroke="currentColor" strokeWidth="3" fill="none"/></IconWrapper>;
    }

    // Accessory
    if (category === 'accessory') {
        if (value === 'none') return <IconWrapper><circle cx="20" cy="20" r="10" stroke="currentColor" fill="none" /><line x1="10" y1="10" x2="30" y2="30" stroke="currentColor"/></IconWrapper>;
        if (value === 'glasses') return <IconWrapper><circle cx="14" cy="20" r="5" stroke="currentColor" fill="none"/><circle cx="26" cy="20" r="5" stroke="currentColor" fill="none"/><line x1="19" y1="20" x2="21" y2="20" stroke="currentColor"/></IconWrapper>;
        if (value === 'sunglasses') return <IconWrapper><rect x="9" y="16" width="10" height="6" fill="currentColor"/><rect x="21" y="16" width="10" height="6" fill="currentColor"/><line x1="19" y1="19" x2="21" y2="19" stroke="currentColor"/></IconWrapper>;
        if (value === 'hat') return <IconWrapper><path d="M5,25 L35,25 L35,22 L30,22 L30,12 Q20,5 10,12 L10,22 L5,22 Z" /></IconWrapper>;
        if (value === 'crown') return <IconWrapper><path d="M10,25 L10,15 L15,20 L20,10 L25,20 L30,15 L30,25 Z" /></IconWrapper>;
        if (value === 'eyepatch') return <IconWrapper><circle cx="15" cy="20" r="5" fill="currentColor"/><path d="M15,20 L30,10" stroke="currentColor"/></IconWrapper>;
    }

    return <IconWrapper><circle cx="20" cy="20" r="10" fill="currentColor" opacity="0.2"/></IconWrapper>;
};

