                className="w-full flex items-center justify-between px-4 py-3 bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/10 rounded-xl text-slate-900 dark:text-white font-bold"
              >
                 <span className="flex items-center gap-2">
                    <Globe size={18} /> {TRANSLATIONS[user.settings.language || Language.ENGLISH].name}
                 </span>
                 <Plus size={16} className="rotate-45" />
