                  disabled={!canChangeUsername}
                  className={`w-full bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/10 rounded-xl px-4 py-3 text-slate-900 dark:text-white focus:outline-none focus:border-atomic-blue ${!canChangeUsername ? 'opacity-50 cursor-not-allowed' : ''}`}
