              <label className="block text-xs font-bold text-slate-500 dark:text-gray-500 uppercase mb-2">New Password</label>
              <input 
                type="password" 
                placeholder="Leave blank to keep current"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="w-full bg-black/5 dark:bg-white/5 border border-black/5 dark:border-white/10 rounded-xl px-4 py-3 text-slate-900 dark:text-white focus:outline-none focus:border-atomic-neon placeholder:text-slate-500 dark:placeholder:text-gray-600"
              />
