            <button 
              onClick={handleUpdateAccount}
              className="mt-4 w-full py-4 bg-blue-600/10 dark:bg-white/10 hover:bg-blue-600/20 dark:hover:bg-white/20 border border-blue-600/20 dark:border-white/20 rounded-xl font-bold text-blue-700 dark:text-atomic-blue transition-colors"
            >
              Update Profile
            </button>
          </div>
        ) : (
          <div className="flex flex-col gap-8">
             <div className="space-y-4">
               <div className="flex items-center gap-3 text-green-700 dark:text-atomic-neon">
                 <Volume2 size={20} />
                 <span className="font-bold uppercase text-sm">{t.sfx}</span>
               </div>
               <input 
                 type="range" min="0" max="100" 
                 value={sfxVol} onChange={(e) => setSfxVol(Number(e.target.value))}
                 className="w-full h-2 bg-gray-300 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-green-600 dark:accent-atomic-neon"
               />
               <div className="text-right text-xs font-mono text-slate-500 dark:text-gray-400">{sfxVol}%</div>
             </div>

             <div className="space-y-4">
               <div className="flex items-center gap-3 text-blue-700 dark:text-atomic-blue">
                 <Music size={20} />
                 <span className="font-bold uppercase text-sm">{t.music}</span>
               </div>
               <input 
                 type="range" min="0" max="100" 
                 value={musicVol} onChange={(e) => setMusicVol(Number(e.target.value))}
                 className="w-full h-2 bg-gray-300 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-blue-600 dark:accent-atomic-blue"
               />
               <div className="text-right text-xs font-mono text-slate-500 dark:text-gray-400">{musicVol}%</div>
             </div>

             <button 
              onClick={handleUpdateAudio}
              className="mt-8 w-full py-4 bg-blue-600 dark:bg-atomic-blue text-white dark:text-atomic-dark rounded-xl font-black uppercase tracking-wider hover:brightness-110 transition-all"
            >
              Save Audio Settings
            </button>
          </div>
        )}

        {message && (
          <div className={`mt-4 p-3 rounded-xl text-sm font-bold text-center animate-in zoom-in ${message.type === 'success' ? 'bg-green-500/20 text-green-700 dark:text-green-400' : 'bg-red-500/20 text-red-700 dark:text-red-400'}`}>
            {message.text}
          </div>
        )}
      </div>

      {showLangModal && <LanguageModal current={user.settings.language || Language.ENGLISH} onSelect={handleLanguageChange} onClose={() => setShowLangModal(false)} />}
    </div>
  );
};

// Main Game Screen (unchanged logic)
const GameScreen: React.FC<{ 
  user: User, 
  difficulty: Difficulty,
  onExit: () => void,
  onScoreUpdate: (points: number) => void
}> = ({ user, difficulty, onExit, onScoreUpdate }) => {
  const t = TRANSLATIONS[user.settings.language || Language.ENGLISH];
  const TOTAL_TIME = 120;
  const [status, setStatus] = useState<GameStatus>(GameStatus.LOADING);
  const [gameData, setGameData] = useState<GameData | null>(null);
  const [selectedCells, setSelectedCells] = useState<GridCell[]>([]);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(TOTAL_TIME);
  const [hintMessage, setHintMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [shuffleCooldown, setShuffleCooldown] = useState(0);
  const [earnedCoins, setEarnedCoins] = useState(0);

  // Interaction State
  const [isDragging, setIsDragging] = useState(false);
  const hasMovedRef = useRef(false);
  const gridRef = useRef<HTMLDivElement>(null);

  // Grid Size Map
  const getGridSize = () => {
      switch(difficulty) {
          case Difficulty.BEGINNER: return 4;
          case Difficulty.NORMAL: return 5;
          case Difficulty.HARD: return 6;
          case Difficulty.EXPERT: return 7;
          default: return 4;
      }
  };
  const gridSize = getGridSize();

  // Initialize Game
  useEffect(() => {
    const init = async () => {
      try {
        setError(null);
        setStatus(GameStatus.LOADING);
        const data = await GeminiService.generateGameLevel(gridSize);
        setGameData(data);
        setStatus(GameStatus.PLAYING);
      } catch (e) {
        console.error(e);
        setError("System Failure. Grid construction interrupted.");
        setStatus(GameStatus.IDLE);
      }
    };
    init();
  }, [gridSize]);

  // Timer
  useEffect(() => {
    if (status !== GameStatus.PLAYING) return;
    if (timeLeft <= 0) {
      finishGame();
      return;
    }
    const timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
    return () => clearInterval(timer);
  }, [status, timeLeft]);

  // Shuffle Cooldown
  useEffect(() => {
    if (shuffleCooldown > 0) {
      const timer = setInterval(() => setShuffleCooldown(prev => prev - 1), 1000);
      return () => clearInterval(timer);
    }
  }, [shuffleCooldown]);

  const finishGame = () => {
      setStatus(GameStatus.FINISHED);
      StorageService.saveScore({
        username: user.username,
        score: score,
        date: new Date().toISOString(),
        difficulty
      });
      // Award coins (10% of score)
      const coins = Math.floor(score / 10);
      setEarnedCoins(coins);
      if (coins > 0) {
          onScoreUpdate(coins);
      }
  };

  // --- Interaction Handling (Tap & Swipe) ---

  const getCellFromTouch = (clientX: number, clientY: number): GridCell | null => {
    if (!gameData || !gridRef.current) return null;
    const element = document.elementFromPoint(clientX, clientY);
    const cellId = element?.getAttribute('data-cell-id');
    if (cellId) {
      const [y, x] = cellId.split('-').map(Number);
      return { id: cellId, char: gameData.grid[y][x], x, y };
    }
    return null;
  };

  const handleStart = (cell: GridCell) => {
    if (status !== GameStatus.PLAYING) return;
    setIsDragging(true);
    hasMovedRef.current = false;

    // If not adjacent to current selection chain, start over, unless we are clicking last one to deselect
    const last = selectedCells[selectedCells.length - 1];

    // Tap to Deselect logic
    if (last && last.id === cell.id) {
        setSelectedCells(prev => prev.slice(0, -1));
        return; 
    }

    // Start new or Add if adjacent
    if (selectedCells.length === 0) {
        setSelectedCells([cell]);
    } else {
        const isAdjacent = Math.abs(last.x - cell.x) <= 1 && Math.abs(last.y - cell.y) <= 1;
        if (isAdjacent && !selectedCells.some(c => c.id === cell.id)) {
            setSelectedCells(prev => [...prev, cell]);
        } else if (!isAdjacent) {
            // Clicked far away -> Start new selection
            setSelectedCells([cell]);
        }
    }
    setHintMessage(null);
  };

  const handleMove = (cell: GridCell) => {
    if (!isDragging || status !== GameStatus.PLAYING) return;

    const last = selectedCells[selectedCells.length - 1];
    if (!last) return;

    // Check undo
    if (selectedCells.length > 1 && selectedCells[selectedCells.length - 2].id === cell.id) {
       setSelectedCells(prev => prev.slice(0, -1));
       hasMovedRef.current = true;
       return;
    }

    const isAdjacent = Math.abs(last.x - cell.x) <= 1 && Math.abs(last.y - cell.y) <= 1;
    const isAlreadySelected = selectedCells.some(c => c.id === cell.id);

    if (isAdjacent && !isAlreadySelected) {
      setSelectedCells(prev => [...prev, cell]);
      hasMovedRef.current = true;
    }
  };

  const handleEnd = () => {
    setIsDragging(false);

    // If we dragged (swiped) multiple cells, auto-submit
    if (hasMovedRef.current && selectedCells.length >= 2) {
        submitWord();
    }
    // If we just tapped (hasMoved = false), keep selected for manual submit
  };

  const submitWord = () => {
    if (selectedCells.length === 0) return;
    const word = selectedCells.map(c => c.char).join('');
    validateWord(word);
    setSelectedCells([]);
    hasMovedRef.current = false;
  };

  const validateWord = (word: string) => {
    if (!gameData) return;
    if (word.length < 2) return; 
    if (foundWords.includes(word)) {
        setHintMessage("Already found!");
        setTimeout(() => setHintMessage(null), 1500);
        return;
    }
    if (gameData.validWords.includes(word)) {
      const points = calculateScore(word.length);
      setScore(prev => prev + points);
      setFoundWords(prev => [word, ...prev]);
    } else {
      setHintMessage("Not in dictionary");
      setTimeout(() => setHintMessage(null), 1500);
    }
  };

  const calculateScore = (len: number) => {
    if (len === 2) return 50;
    if (len === 3) return 100;
    if (len === 4) return 200;
    if (len >= 5) return 400 + (len - 5) * 100;
    return 0;
  };

  const requestHint = async () => {
     if (!gameData) return;
     setScore(prev => Math.max(0, prev - 50)); 
     const hint = await GeminiService.getHint(gameData.grid, foundWords, gameData.validWords);
     setHintMessage(hint);
  };

  const handleShuffle = async () => {
    if (!gameData || shuffleCooldown > 0) return;
    setShuffleCooldown(10); 
    const newData = await GeminiService.shuffleGrid(gameData.grid);
    setGameData(newData);
    setSelectedCells([]);
  };

  if (status === GameStatus.LOADING) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
        <AtomSpinner />
        <p className="animate-pulse text-xl font-bold text-blue-600 dark:text-atomic-blue">Constructing {difficulty} Grid...</p>
        <p className="text-xs text-slate-500 dark:text-gray-500">Retrieving Dictionary Protocols...</p>
      </div>
    );
  }

  if (error || status === GameStatus.IDLE) {
    return (
        <div className="flex flex-col items-center justify-center h-[60vh] gap-4 p-8 text-center">
            <AlertTriangle className="text-red-500 w-16 h-16" />
            <h3 className="text-2xl font-bold text-slate-900 dark:text-white">Connection Error</h3>
            <p className="text-slate-600 dark:text-gray-400">{error || "Unknown error occurred."}</p>
            <div className="flex gap-4 mt-4">
                <button onClick={onExit} className="px-6 py-3 rounded-xl bg-slate-700 text-white font-bold">{t.menu}</button>
                <button onClick={() => window.location.reload()} className="px-6 py-3 rounded-xl bg-blue-600 dark:bg-atomic-blue text-white dark:text-atomic-dark font-bold">{t.retry}</button>
            </div>
        </div>
    );
  }

  if (status === GameStatus.FINISHED) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-6 animate-in zoom-in">
        <h2 className="text-4xl font-black text-green-600 dark:text-atomic-neon uppercase">{t.levelComplete}</h2>
        <div className="p-8 bg-white/60 dark:bg-white/10 backdrop-blur-lg rounded-2xl border border-black/5 dark:border-white/20 text-center w-64">
          <p className="text-slate-500 dark:text-gray-400 uppercase tracking-widest text-sm mb-2">{t.score}</p>
          <p className="text-6xl font-black text-slate-900 dark:text-white">{score}</p>
          <div className="flex items-center justify-center gap-2 mt-4 text-yellow-500">
             <Coins /> <span className="font-bold text-xl">+{earnedCoins}</span>
          </div>
          <p className="text-slate-500 dark:text-gray-400 text-xs mt-2">{difficulty} Mode</p>
        </div>
        <div className="flex gap-4">
            <button onClick={onExit} className="px-6 py-3 rounded-xl bg-slate-600 text-white font-bold hover:bg-slate-500">
                {t.menu}
            </button>
            <button onClick={() => window.location.reload()} className="px-6 py-3 rounded-xl bg-blue-600 dark:bg-atomic-blue text-white dark:text-atomic-dark font-bold hover:brightness-110">
                {t.playAgain}
            </button>
        </div>
      </div>
    );
  }

  const currentWord = selectedCells.map(c => c.char).join('');
  const shuffleLocked = timeLeft > (TOTAL_TIME / 2);
  const shuffleDisabled = shuffleLocked || shuffleCooldown > 0;

  return (
    <div className="flex flex-col h-full max-w-md mx-auto relative">
      <div className="flex justify-between items-center px-4 py-2 bg-white/60 dark:bg-white/5 backdrop-blur-md rounded-b-2xl mb-4 shadow-lg border-b border-black/5 dark:border-white/10">
        <div className="flex flex-col">
            <span className="text-xs text-slate-500 dark:text-gray-400 uppercase">{t.score}</span>
            <span className="text-2xl font-black text-green-700 dark:text-atomic-neon">{score}</span>
        </div>
        <div className="flex items-center gap-2"><Logo size="sm" /></div>
        <div className="flex flex-col items-end">
            <span className="text-xs text-slate-500 dark:text-gray-400 uppercase">Time</span>
            <span className={`text-2xl font-black ${timeLeft < 30 ? 'text-red-500 animate-pulse' : 'text-slate-900 dark:text-white'}`}>
                {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
            </span>
        </div>
      </div>

      <div className="h-8 flex justify-center items-center mb-2">
        {hintMessage && (
            <span className="px-3 py-1 bg-orange-100 dark:bg-atomic-orange/20 text-orange-600 dark:text-atomic-orange border border-orange-500/50 rounded-full text-sm font-bold animate-in slide-in-from-top">
                {hintMessage}
            </span>
        )}
      </div>

      <div className="h-16 flex items-center justify-center mb-4">
        <div className={`text-4xl font-black tracking-widest transition-all ${currentWord.length > 0 ? 'scale-110 text-slate-900 dark:text-white' : 'scale-100 text-slate-400 dark:text-gray-500/50'}`}>
             {currentWord || (hasMovedRef.current ? "..." : "SWIPE / CLICK")}
        </div>
      </div>

      <div 
        ref={gridRef}
        className="aspect-square w-full p-4 touch-none select-none"
        onMouseLeave={handleEnd}
        onMouseUp={handleEnd}
        onTouchEnd={handleEnd}
      >
        <div 
            className="grid gap-2 h-full"
            style={{ 
                gridTemplateColumns: `repeat(${gridSize}, minmax(0, 1fr))`,
                gridTemplateRows: `repeat(${gridSize}, minmax(0, 1fr))` 
            }}
            onTouchMove={(e) => {
                const touch = e.touches[0];
                const cell = getCellFromTouch(touch.clientX, touch.clientY);
                if (cell) handleMove(cell);
            }}
        >
            {gameData?.grid.map((row, y) => 
                row.map((char, x) => {
                    const isSelected = selectedCells.some(c => c.x === x && c.y === y);
                    const cellData: GridCell = { id: `${y}-${x}`, char, x, y };

                    return (
                        <div
                            key={`${y}-${x}`}
                            data-cell-id={`${y}-${x}`}
                            onMouseDown={() => handleStart(cellData)}
                            onMouseEnter={() => handleMove(cellData)}
                            className={`
                                relative flex items-center justify-center font-bold rounded-lg cursor-pointer transition-all duration-150
                                shadow-[inset_0_-2px_4px_rgba(0,0,0,0.2)]
                                ${gridSize > 5 ? 'text-xl' : 'text-3xl'}
                                ${isSelected 
                                    ? 'bg-blue-600 text-white dark:bg-atomic-blue dark:text-atomic-dark scale-95 shadow-[0_0_10px_rgba(37,99,235,0.6)] dark:shadow-[0_0_10px_rgba(0,243,255,0.6)] z-10' 
                                    : 'bg-white/40 dark:bg-white/10 hover:bg-white/60 dark:hover:bg-white/20 text-slate-900 dark:text-white backdrop-blur-sm border border-white/20 dark:border-white/10'}
                            `}
                        >
                            {char}
                        </div>
                    );
                })
            )}
        </div>
      </div>

      <div className="flex justify-around items-center px-4 mt-4 gap-2">
         <button onClick={onExit} className="p-3 rounded-full bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-500 hover:bg-red-500 hover:text-white transition-colors">
            <X size={24} />
         </button>

         <button 
            onClick={requestHint}
            className="flex items-center gap-2 px-4 py-3 rounded-full bg-orange-500 dark:bg-atomic-orange text-white font-bold shadow-lg hover:brightness-110 active:scale-95 transition-all"
         >
            <Lightbulb size={20} />
         </button>

         <button 
            onClick={handleShuffle}
            disabled={shuffleDisabled}
            className={`
                relative flex items-center justify-center p-3 rounded-full transition-all
                ${shuffleDisabled 
                    ? 'bg-slate-300 dark:bg-gray-700/50 text-slate-500 dark:text-gray-500 cursor-not-allowed' 
                    : 'bg-purple-100 dark:bg-purple-500/20 text-purple-600 dark:text-purple-400 hover:bg-purple-500 hover:text-white shadow-lg'}
            `}
         >
            <Shuffle size={24} />
            {shuffleCooldown > 0 && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 rounded-full font-bold text-white text-xs">
                    {shuffleCooldown}
                </div>
            )}
         </button>

         <button 
             onClick={submitWord}
             className={`p-3 rounded-full transition-all ${
                selectedCells.length >= 2 
                ? 'bg-green-600 dark:bg-atomic-neon text-white dark:text-atomic-dark shadow-lg dark:shadow-[0_0_15px_rgba(57,255,20,0.5)] scale-110' 
                : 'bg-green-600/20 dark:bg-atomic-neon/20 text-green-700 dark:text-atomic-neon opacity-50'
             }`}
         >
            <Check size={24} />
         </button>
      </div>

      <div className="flex-1 overflow-hidden mt-6 bg-white/60 dark:bg-black/20 rounded-t-2xl backdrop-blur-md border-t border-black/5 dark:border-white/10">
         <div className="p-4">
             <div className="flex justify-between items-baseline mb-2">
                 <h3 className="text-xs font-bold uppercase text-slate-500 dark:text-gray-400">{t.foundWords} ({foundWords.length})</h3>
                 <span className="text-[10px] text-slate-500 dark:text-gray-600">Total: {gameData?.validWords.length}</span>
             </div>
             <div className="flex flex-wrap gap-2 overflow-y-auto max-h-[20vh]">
                 {foundWords.map((w, i) => (
                     <span key={i} className="px-3 py-1 bg-black/5 dark:bg-white/10 rounded-md text-sm font-medium animate-in zoom-in text-slate-900 dark:text-white">{w}</span>
                 ))}
             </div>
         </div>
      </div>
    </div>
  );
};

