// --- Main App Component ---

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'HOME' | 'GAME' | 'SCORES' | 'SETTINGS' | 'CUSTOMIZE'>('HOME');
  const [darkMode, setDarkMode] = useState(true);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.NORMAL);

  useEffect(() => {
    const saved = StorageService.getSession();
    if (saved) setUser(saved);
  }, []);

  const handleLogout = () => {
    StorageService.clearSession();
    setUser(null);
    setView('HOME');
  };

  const toggleTheme = () => {
    setDarkMode(!darkMode);
  };

  // Helper to get current translation based on user settings
  const t = user ? TRANSLATIONS[user.settings.language || Language.ENGLISH] : TRANSLATIONS[Language.ENGLISH];

  const handleScoreUpdate = (earnedCoins: number) => {
      if (user) {
          const updatedUser = { ...user, coins: user.coins + earnedCoins };
          StorageService.saveSession(updatedUser);
          StorageService.updateUserProfile(updatedUser); // Update in DB too
          setUser(updatedUser);
      }
  };

  return (
    <div className={`min-h-screen font-sans transition-colors duration-500 ${darkMode ? 'dark text-white' : 'text-slate-900'}`}>
      <AtomicBackground darkMode={darkMode} />

      {/* App Container */}
      <div className="relative z-10 container mx-auto h-screen flex flex-col">

        {/* Persistent Top Bar */}
         <div className="flex justify-between items-center p-4">
            {user && view === 'HOME' ? (
                <button onClick={handleLogout} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 text-slate-500 dark:text-gray-400">
                    <LogOut size={20} />
                </button>
            ) : <div className="w-10"></div>}

            <div className="flex gap-2">
               {user && view === 'HOME' && (
                   <button onClick={() => setView('SETTINGS')} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 text-slate-500 dark:text-gray-300">
                      <Settings size={20} />
                   </button>
               )}
               <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors bg-white/40 dark:bg-white/5 backdrop-blur-sm text-slate-900 dark:text-white">
                  {darkMode ? <Sun size={20} /> : <Moon size={20} />}
               </button>
            </div>
         </div>

        {/* View Routing */}
        <main className="flex-1 overflow-hidden">
            {!user ? (
                <LoginScreen onLogin={setUser} />
            ) : view === 'HOME' ? (
                <div className="flex flex-col items-center justify-center h-[75vh] gap-6 animate-in fade-in">
                    <Logo size="lg" />

                    <div className="flex flex-col items-center justify-center relative">
                         {/* Avatar Display */}
                         <div className="w-32 h-32 bg-gradient-to-b from-blue-100 to-white dark:from-slate-800 dark:to-slate-900 rounded-full border-4 border-white/20 mb-4 overflow-hidden shadow-2xl relative group">
                            <Avatar config={user.avatar} language={user.settings.language} className="w-full h-full transform group-hover:scale-105 transition-transform object-cover" />
                         </div>

                        <div className="text-center space-y-1 animate-in slide-in-from-bottom duration-700">
                            <p className="text-sm text-slate-500 dark:text-gray-400 uppercase tracking-widest">{t.welcome}</p>
                            <h1 className="text-3xl font-black text-slate-900 dark:text-white">{user.username}</h1>
                            <div className="flex items-center justify-center gap-1 text-yellow-500">
                                <Coins size={14} /> <span className="font-bold">{user.coins}</span> <span className="text-xs uppercase">{t.coins}</span>
                            </div>
                        </div>

                        <button 
                            onClick={() => setView('CUSTOMIZE')}
                            className="absolute -right-8 top-0 p-2 bg-white/20 dark:bg-white/5 rounded-full hover:bg-white/40 transition-colors"
                        >
                            <Shirt size={16} className="text-slate-600 dark:text-gray-300" />
                        </button>
                    </div>

                    <div className="flex flex-col gap-3 w-64">
                        {/* Difficulty Selector */}
                        <div className="flex justify-between bg-white/60 dark:bg-black/20 rounded-xl p-1 border border-black/5 dark:border-white/10">
                            {Object.values(Difficulty).map((d) => (
                                <button
                                    key={d}
                                    onClick={() => setDifficulty(d)}
                                    className={`
                                        flex-1 py-2 text-[10px] font-bold uppercase rounded-lg transition-all
                                        ${difficulty === d ? 'bg-blue-600 text-white dark:bg-atomic-blue dark:text-atomic-dark shadow-md' : 'text-slate-500 dark:text-gray-500 hover:text-slate-900 dark:hover:text-white'}
                                    `}
                                >
                                    {d.charAt(0)}
                                </button>
                            ))}
                        </div>
                        <div className="text-center text-[10px] text-slate-400 dark:text-gray-500 uppercase tracking-widest -mt-1 mb-1">
                            {difficulty} Mode
                        </div>

                        <button 
                            onClick={() => setView('GAME')}
                            className="group relative px-8 py-4 bg-blue-600 dark:bg-atomic-blue text-white dark:text-atomic-dark font-black text-xl rounded-xl shadow-lg dark:shadow-[0_0_20px_rgba(0,243,255,0.4)] hover:scale-105 transition-all overflow-hidden"
                        >
                            <span className="relative z-10 flex items-center justify-center gap-2">
                                <Play fill="currentColor" /> {t.play}
                            </span>
                            <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"/>
                        </button>

                        <button 
                            onClick={() => setView('SCORES')}
                            className="flex items-center justify-center gap-2 px-8 py-4 bg-white/60 dark:bg-white/10 backdrop-blur-md border border-black/5 dark:border-white/20 font-bold rounded-xl hover:bg-white/80 dark:hover:bg-white/20 text-slate-800 dark:text-white transition-all"
                        >
                            <Trophy className="text-orange-500 dark:text-atomic-orange" /> {t.leaderboard}
                        </button>
                    </div>
                </div>
            ) : view === 'GAME' ? (
                <GameScreen user={user} difficulty={difficulty} onExit={() => setView('HOME')} onScoreUpdate={handleScoreUpdate} />
            ) : view === 'SETTINGS' ? (
                <SettingsScreen user={user} onBack={() => setView('HOME')} onUpdateUser={setUser} onCustomize={() => setView('CUSTOMIZE')} />
            ) : view === 'CUSTOMIZE' ? (
                <CustomizeScreen user={user} onUpdateUser={setUser} onBack={() => setView('HOME')} />
            ) : (
                <LeaderboardScreen onBack={() => setView('HOME')} language={user.settings.language || Language.ENGLISH} />
            )}
        </main>
      </div>
    </div>
  );
}

const AtomSpinner = () => (
    <div className="relative w-16 h-16 animate-spin-slow">
        <div className="absolute inset-0 border-2 border-transparent border-t-blue-500 dark:border-t-atomic-blue rounded-full animate-spin"></div>
        <div className="absolute inset-2 border-2 border-transparent border-b-green-500 dark:border-b-atomic-neon rounded-full animate-pulse"></div>
    </div>
);

export default App;

import React, { useMemo } from 'react';
import { AvatarConfig, Language } from '../types';

interface AvatarProps {
  config: AvatarConfig;
  language?: Language;
  className?: string;
}

const Avatar: React.FC<AvatarProps> = ({ config, language = Language.ENGLISH, className }) => {
  const isPirate = language === Language.PIRATE;
  const uniqueId = useMemo(() => Math.random().toString(36).substr(2, 9), []);

  // --- Color Utilities ---
  const adjustColor = (hex: string, amt: number) => {
    let usePound = false;
    if (hex.startsWith("#")) {
      hex = hex.slice(1);
      usePound = true;
    }
    let num = parseInt(hex, 16);
    let r = (num >> 16) + amt;
    if (r > 255) r = 255; else if (r < 0) r = 0;
    let b = ((num >> 8) & 0x00FF) + amt;
    if (b > 255) b = 255; else if (b < 0) b = 0;
    let g = (num & 0x0000FF) + amt;
    if (g > 255) g = 255; else if (g < 0) g = 0;
    return (usePound ? "#" : "") + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
  };

  // Base Colors & Derived Shades
  const skinBase = config.skinTone;
  const skinShadow = adjustColor(skinBase, -30);
  const skinHighlight = adjustColor(skinBase, 20);
  const skinBlush = adjustColor(skinBase, -10); // slightly redder/darker for cheeks

  const hairBase = config.hairColor;
  const hairDark = adjustColor(hairBase, -50);
  const hairLight = adjustColor(hairBase, 40);

  const topBase = config.topColor;
  const topDark = adjustColor(topBase, -40);
  const topLight = adjustColor(topBase, 30);

  const botBase = config.bottomColor;
  const botDark = adjustColor(botBase, -40);

  return (
    <svg 
      viewBox="0 0 300 600" 
      className={className} 
      xmlns="http://www.w3.org/2000/svg" 
      preserveAspectRatio="xMidYMid meet"
      shapeRendering="geometricPrecision"
    >
      <defs>
        {/* --- SKIN GRADIENTS --- */}
        <radialGradient id={`skin-grad-${uniqueId}`} cx="40%" cy="35%" r="50%">
          <stop offset="0%" stopColor={skinHighlight} />
          <stop offset="100%" stopColor={skinBase} />
        </radialGradient>

        <radialGradient id={`blush-grad-${uniqueId}`} cx="50%" cy="50%" r="50%">
          <stop offset="0%" stopColor="#ffb7b2" stopOpacity="0.4" />
          <stop offset="100%" stopColor={skinBase} stopOpacity="0" />
        </radialGradient>

        {/* --- CLOTHING GRADIENTS --- */}
        <linearGradient id={`top-grad-${uniqueId}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor={topLight} />
          <stop offset="50%" stopColor={topBase} />
          <stop offset="100%" stopColor={topDark} />
        </linearGradient>

        <linearGradient id={`bot-grad-${uniqueId}`} x1="0.5" y1="0" x2="0.5" y2="1">
          <stop offset="0%" stopColor={botBase} />
          <stop offset="100%" stopColor={botDark} />
        </linearGradient>

        {/* --- HAIR GRADIENT --- */}
        <linearGradient id={`hair-grad-${uniqueId}`} x1="0" y1="0" x2="0" y2="1">
           <stop offset="0%" stopColor={hairLight} />
           <stop offset="50%" stopColor={hairBase} />
           <stop offset="100%" stopColor={hairDark} />
        </linearGradient>

        {/* --- EYE GRADIENTS --- */}
        <radialGradient id={`eye-iris-${uniqueId}`} cx="50%" cy="50%" r="50%">
          <stop offset="60%" stopColor="#4a3b2a" /> {/* Brownish base for now */}
          <stop offset="100%" stopColor="#1a110a" />
        </radialGradient>

        {/* --- FILTERS --- */}
        <filter id={`drop-shadow-${uniqueId}`} x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur in="SourceAlpha" stdDeviation="2"/>
          <feOffset dx="0" dy="2" result="offsetblur"/>
          <feComponentTransfer>
            <feFuncA type="linear" slope="0.2"/>
          </feComponentTransfer>
          <feMerge> 
            <feMergeNode/>
            <feMergeNode in="SourceGraphic"/> 
          </feMerge>
        </filter>

        <filter id={`hair-shadow-${uniqueId}`}>
           <feDropShadow dx="0" dy="4" stdDeviation="4" floodOpacity="0.3"/>
        </filter>
      </defs>

      {/* ================= GROUP: BODY & CLOTHES ================= */}
      <g transform="translate(0, 50)">

        {/* --- BACK HAIR (Behind Head/Body) --- */}
        {(config.hairStyle === 'long' || config.hairStyle === 'bob') && (
            <path 
              d="M90,80 C70,120 60,180 80,220 L220,220 C240,180 230,120 210,80" 
              fill={hairDark} 
            />
        )}

        {/* --- LEGS / BOTTOMS --- */}
        <g transform="translate(0, 300)">
            {/* Legs (Skin) */}
            <path d="M100,0 L100,200 L130,200 L130,0" fill={skinShadow} /> {/* Left Leg */}
            <path d="M170,0 L170,200 L200,200 L200,0" fill={skinShadow} /> {/* Right Leg */}

            {/* Pants */}
            {config.bottomType === 'pants' && (
               <path 
                 d="M95,0 L90,220 L135,220 L135,60 L165,60 L165,220 L210,220 L205,0 Z" 
                 fill={`url(#bot-grad-${uniqueId})`}
               />
            )}

            {/* Shorts */}
            {config.bottomType === 'shorts' && (
               <path 
                 d="M95,0 L90,100 L135,100 L135,60 L165,60 L165,100 L210,100 L205,0 Z" 
                 fill={`url(#bot-grad-${uniqueId})`}
               />
            )}

            {/* Skirt */}
            {config.bottomType === 'skirt' && (
                <path 
                  d="M95,0 L70,140 Q150,150 230,140 L205,0 Z"
                  fill={`url(#bot-grad-${uniqueId})`}
                />
            )}

            {/* Shoes */}
            <g transform="translate(0, 220)">
               <path d="M90,0 Q80,20 100,25 L135,25 Q145,20 135,0 Z" fill="#333" />
               <path d="M165,0 Q155,20 175,25 L210,25 Q220,20 210,0 Z" fill="#333" />
            </g>
        </g>

        {/* --- TORSO --- */}
        <g transform="translate(0, 140)">
             {/* Neck */}
             <path d="M125,-60 L125,10 L175,10 L175,-60" fill={skinShadow} />
             {/* Neck Shadow (under chin) */}
             <ellipse cx="150" cy="-45" rx="25" ry="10" fill="rgba(0,0,0,0.2)" />

             {/* Shirt Body */}
             <path 
               d="M85,0 C70,20 70,160 85,180 L215,180 C230,160 230,20 215,0 Q150,-10 85,0" 
               fill={`url(#top-grad-${uniqueId})`}
               filter={`url(#drop-shadow-${uniqueId})`}
             />

             {/* Arms */}
             {config.topType === 'tshirt' ? (
                // Short Sleeves
                <g>
                    {/* Skin Arms */}
                    <path d="M60,40 L60,150 Q75,160 90,150 L90,40" fill={skinBase} />
                    <path d="M210,40 L210,150 Q225,160 240,150 L240,40" fill={skinBase} />
                    {/* Sleeves */}
                    <path d="M85,5 L45,45 L75,70 L100,30" fill={`url(#top-grad-${uniqueId})`} />
                    <path d="M215,5 L255,45 L225,70 L200,30" fill={`url(#top-grad-${uniqueId})`} />
                </g>
             ) : (
                // Long Sleeves (Hoodie/Suit/Shirt)
                <g>
                    <path d="M90,10 L50,150 L80,160 L105,40" fill={`url(#top-grad-${uniqueId})`} />
                    <path d="M210,10 L250,150 L220,160 L195,40" fill={`url(#top-grad-${uniqueId})`} />
                    {/* Hands */}
                    <circle cx="65" cy="165" r="15" fill={skinBase} />
                    <circle cx="235" cy="165" r="15" fill={skinBase} />
                </g>
             )}

             {/* Top Details */}
             {config.topType === 'hoodie' && (
                 <g>
                    <path d="M110,0 Q150,50 190,0" fill="none" stroke={topDark} strokeWidth="6" opacity="0.5"/>
                    <rect x="145" y="40" width="10" height="80" rx="5" fill={topDark} opacity="0.3" /> {/* Zipper/Pocket area */}
                 </g>
             )}

             {config.topType === 'suit' && (
                 <g>
                    <path d="M150,0 L150,180" stroke="rgba(0,0,0,0.2)" strokeWidth="1" />
                    <path d="M150,0 L130,40 L150,80 L170,40 Z" fill="#a00" /> {/* Red Tie */}
                    <path d="M150,0 L120,60 L100,0" fill="white" opacity="0.8" /> {/* White Collar Left */}
                    <path d="M150,0 L180,60 L200,0" fill="white" opacity="0.8" /> {/* White Collar Right */}
                 </g>
             )}

            {config.topType === 'shirt' && (
                 <g>
                    <path d="M150,0 L150,180" stroke="rgba(0,0,0,0.2)" strokeWidth="2" />
                    <circle cx="158" cy="40" r="3" fill="rgba(0,0,0,0.3)" />
                    <circle cx="158" cy="80" r="3" fill="rgba(0,0,0,0.3)" />
                    <circle cx="158" cy="120" r="3" fill="rgba(0,0,0,0.3)" />
                    {/* Collar */}
                    <path d="M150,0 L120,20 L100,0" fill={`url(#top-grad-${uniqueId})`} stroke={topDark} strokeWidth="1"/>
                    <path d="M150,0 L180,20 L200,0" fill={`url(#top-grad-${uniqueId})`} stroke={topDark} strokeWidth="1"/>
                 </g>
             )}
        </g>

        {/* ================= GROUP: HEAD ================= */}
        <g transform="translate(150, 75)">

            {/* Head Shape (Rounded Rectangle/Oval Hybrid) */}
            <path 
              d="M-55,-60 C-55,-100 55,-100 55,-60 L55,20 C55,70 30,90 0,90 C-30,90 -55,70 -55,20 Z" 
              fill={`url(#skin-grad-${uniqueId})`}
              filter={`url(#drop-shadow-${uniqueId})`}
            />

            {/* Ears */}
            <g transform="translate(0, 10)">
                <path d="M-55,-10 Q-65,0 -55,15" stroke={skinShadow} strokeWidth="3" fill={skinBase} />
                <path d="M55,-10 Q65,0 55,15" stroke={skinShadow} strokeWidth="3" fill={skinBase} />
            </g>

            {/* Cheeks / Blush */}
            <ellipse cx="-30" cy="30" rx="15" ry="10" fill={`url(#blush-grad-${uniqueId})`} />
            <ellipse cx="30" cy="30" rx="15" ry="10" fill={`url(#blush-grad-${uniqueId})`} />

            {/* --- FACE FEATURES --- */}
            <g transform="translate(0, 10)">

                {/* Nose - Defined by shadow */}
                <path 
                  d="M-5,20 Q0,25 5,20" 
                  stroke={skinShadow} strokeWidth="2" fill="none" opacity="0.6"
                />
                <circle cx="0" cy="18" r="6" fill={skinShadow} opacity="0.1" />

                {/* Mouth */}
                <path 
                  d="M-15,45 Q0,55 15,45" 
                  stroke="#a36e57" strokeWidth="3" strokeLinecap="round" fill="none" 
                />

                {/* Eyes */}
                <g transform="translate(0, -5)">
                    {/* Left Eye */}
                    <g transform="translate(-25, 0)">
                        <ellipse rx="14" ry="16" fill="#fff" />
                         {(!isPirate && config.accessory !== 'sunglasses') && (
                            <>
                                {/* Iris */}
                                <circle r="8" fill={`url(#eye-iris-${uniqueId})`} />
                                {/* Pupil */}
                                <circle r="4" fill="#000" />
                                {/* Highlights */}
                                <circle cx="3" cy="-3" r="3" fill="#fff" opacity="0.9" />
                                <circle cx="-3" cy="4" r="1.5" fill="#fff" opacity="0.6" />
                            </>
                         )}
                    </g>
                    {/* Right Eye */}
                    <g transform="translate(25, 0)">
                        <ellipse rx="14" ry="16" fill="#fff" />
                        {(!isPirate && config.accessory !== 'sunglasses') && (
                            <>
                                <circle r="8" fill={`url(#eye-iris-${uniqueId})`} />
                                <circle r="4" fill="#000" />
                                <circle cx="3" cy="-3" r="3" fill="#fff" opacity="0.9" />
                                <circle cx="-3" cy="4" r="1.5" fill="#fff" opacity="0.6" />
                            </>
                         )}
                    </g>
                </g>

                {/* Eyebrows */}
                <g transform="translate(0, -25)">
                     <path d="M-40,0 Q-25,-5 -10,0" stroke={hairBase} strokeWidth="4" strokeLinecap="round" fill="none" />
                     <path d="M40,0 Q25,-5 10,0" stroke={hairBase} strokeWidth="4" strokeLinecap="round" fill="none" />
                </g>

                {/* Beard Layer */}
                {config.beard === 'mustache' && (
                    <path d="M-15,35 Q0,30 15,35 Q0,45 -15,35" fill={hairBase} />
                )}
                {config.beard === 'full' && (
                    <path d="M-55,0 L-55,30 Q-55,90 0,90 Q55,90 55,30 L55,0 L45,0 L45,30 Q45,75 0,75 Q-45,75 -45,30 L-45,0 Z" fill={hairBase} opacity="0.9" />
                )}
                {config.beard === 'stubble' && (
                     <path d="M-55,20 Q0,100 55,20" fill="none" stroke={hairBase} strokeWidth="50" strokeOpacity="0.1" />
                )}

            </g> {/* End Face Features */}

             {/* Accessories - Glasses */}
             {config.accessory === 'glasses' && !isPirate && (
                <g transform="translate(0, 5)">
                    <circle cx="-25" cy="0" r="18" stroke="#333" strokeWidth="2" fill="rgba(255,255,255,0.1)" />
                    <circle cx="25" cy="0" r="18" stroke="#333" strokeWidth="2" fill="rgba(255,255,255,0.1)" />
                    <path d="M-7,0 Q0,-5 7,0" stroke="#333" strokeWidth="2" fill="none"/>
                    <line x1="-43" y1="0" x2="-55" y2="-5" stroke="#333" strokeWidth="2" />
                    <line x1="43" y1="0" x2="55" y2="-5" stroke="#333" strokeWidth="2" />
                </g>
             )}
             {config.accessory === 'sunglasses' && !isPirate && (
                 <g transform="translate(0, 5)">
                    <path d="M-50,-10 L0,-10 L0,15 Q-25,25 -50,15 Z" fill="#111" stroke="#000" strokeWidth="1" />
                    <path d="M50,-10 L0,-10 L0,15 Q25,25 50,15 Z" fill="#111" stroke="#000" strokeWidth="1" />
                    <line x1="-50" y1="-5" x2="-56" y2="-8" stroke="#000" strokeWidth="3" />
                    <line x1="50" y1="-5" x2="56" y2="-8" stroke="#000" strokeWidth="3" />
                 </g>
             )}
             {(isPirate || config.accessory === 'eyepatch') && (
                <g transform="translate(0, 5)">
                    <circle cx="-25" cy="0" r="16" fill="#111" />
                    <path d="M-25,0 L50,-40" stroke="#111" strokeWidth="2" />
                    <path d="M-25,0 L-50,-40" stroke="#111" strokeWidth="2" />
                </g>
             )}

            {/* --- FRONT HAIR --- */}
            <g filter={`url(#hair-shadow-${uniqueId})`}>
                {config.hairStyle === 'short' && (
                    <path 
                      d="M-55,-20 C-55,-80 55,-80 55,-20 C55,-50 30,-50 10,-20 C0,-60 -40,-50 -55,-20" 
                      fill={`url(#hair-grad-${uniqueId})`} 
                    />
                )}
                {config.hairStyle === 'spiky' && (
                     <path 
                      d="M-55,-30 L-40,-70 L-20,-50 L0,-80 L20,-50 L40,-70 L55,-30 C55,-20 0,-20 -55,-30" 
                      fill={`url(#hair-grad-${uniqueId})`} 
                    />
                )}
                 {config.hairStyle === 'long' && (
                     <path 
                      d="M-55,-30 Q-20,-90 55,-30 L60,100 L40,100 L40,20 Q10,-10 -20,20 L-30,100 L-60,100 Z"
                      fill={`url(#hair-grad-${uniqueId})`} 
                    />
                )}
                {config.hairStyle === 'bob' && (
                     <path 
                      d="M-55,-30 Q0,-90 55,-30 L60,50 L40,50 L40,10 Q10,-10 -20,10 L-30,50 L-60,50 Z"
                      fill={`url(#hair-grad-${uniqueId})`} 
                    />
                )}

                {/* Hair Shine/Highlight */}
                 {config.hairStyle !== 'bald' && (
                    <path 
                        d="M-30,-50 Q0,-65 30,-50" 
                        stroke="rgba(255,255,255,0.2)" strokeWidth="6" strokeLinecap="round" fill="none" 
                    />
                 )}
            </g>

            {/* Hats / Headwear */}
            {config.accessory === 'hat' && (
                 <g transform="translate(0, -60)" filter={`url(#drop-shadow-${uniqueId})`}>
                    <ellipse cx="0" cy="0" rx="60" ry="20" fill="#222" /> {/* Brim */}
                    <path d="M-35,0 L-35,-30 Q0,-45 35,-30 L35,0" fill="#333" /> {/* Top */}
                    <rect x="-35" y="-5" width="70" height="5" fill="#c00" /> {/* Band */}
                 </g>
            )}
             {config.accessory === 'crown' && (
                 <g transform="translate(0, -70)" filter={`url(#drop-shadow-${uniqueId})`}>
                    <path d="M-30,20 L-30,0 L-10,15 L0,-10 L10,15 L30,0 L30,20 Z" fill="#FFD700" stroke="#DAA520" strokeWidth="2" />
                    <circle cx="0" cy="10" r="3" fill="#c00"/>
                 </g>
            )}

        </g> {/* End Head Group */}

      </g> {/* End Body Group */}

      {/* Pirate Parrot (Foreground) */}
      {isPirate && (
          <g transform="translate(220, 180) rotate(-10)">
              <path d="M0,20 Q-5,0 10,5 Q20,10 20,30 L15,50 L0,50 Z" fill="#D00" />
              <circle cx="10" cy="10" r="4" fill="#FFF" />
              <circle cx="11" cy="10" r="1.5" fill="#000" />
              <path d="M12,10 L20,12 L15,18 Z" fill="#FB1" />
              <path d="M-5,30 L5,30 L0,50 Z" fill="#00F" />
          </g>
      )}

    </svg>
  );
};

export default Avatar;

import React, { useMemo } from 'react';
import { AvatarConfig, Language } from '../types';

interface AvatarProps {
  config: AvatarConfig;
  language?: Language;
  className?: string;
}

const Avatar: React.FC<AvatarProps> = ({ config, language = Language.ENGLISH, className }) => {
  const isPirate = language === Language.PIRATE;
  const uniqueId = useMemo(() => Math.random().toString(36).substr(2, 9), []);

  const adjustColor = (hex: string, amt: number) => {
    let usePound = false;
    if (hex.startsWith("#")) {
      hex = hex.slice(1);
      usePound = true;
    }
    let num = parseInt(hex, 16);
    let r = (num >> 16) + amt;
    if (r > 255) r = 255; else if (r < 0) r = 0;
    let b = ((num >> 8) & 0x00FF) + amt;
    if (b > 255) b = 255; else if (b < 0) b = 0;
    let g = (num & 0x0000FF) + amt;
    if (g > 255) g = 255; else if (g < 0) g = 0;
    return (usePound ? "#" : "") + (g | (b << 8) | (r << 16)).toString(16).padStart(6, '0');
  };

  const skinBase = config.skinTone;
  const skinShadow = adjustColor(skinBase, -45);
  const skinHighlight = adjustColor(skinBase, 25);
  const skinWarmth = adjustColor(skinBase, -15); // For blush/ears

  const hairBase = config.hairColor;
  const hairDark = adjustColor(hairBase, -60);
  const hairLight = adjustColor(hairBase, 50);

  const topBase = config.topColor;
  const topDark = adjustColor(topBase, -50);
  const topLight = adjustColor(topBase, 40);

  const botBase = config.bottomColor;
  const botDark = adjustColor(botBase, -50);

  return (
    <svg 
      viewBox="0 0 300 600" 
      className={className} 
      xmlns="http://www.w3.org/2000/svg" 
      preserveAspectRatio="xMidYMid meet"
      shapeRendering="geometricPrecision"
    >
      <defs>
        {/* --- GLOBAL SHADOWS --- */}
        <filter id={`occlusion-${uniqueId}`}>
          <feDropShadow dx="0" dy="4" stdDeviation="5" floodOpacity="0.4"/>
        </filter>

        {/* --- SKIN: Subsurface Scattering Effect --- */}
        <radialGradient id={`skin-grad-${uniqueId}`} cx="35%" cy="30%" r="65%">
          <stop offset="0%" stopColor={skinHighlight} />
          <stop offset="60%" stopColor={skinBase} />
          <stop offset="100%" stopColor={skinWarmth} />
        </radialGradient>

        {/* --- EYES: Realistic Iris --- */}
        <radialGradient id={`iris-grad-${uniqueId}`} cx="45%" cy="45%" r="50%">
          <stop offset="0%" stopColor="#6d4c41" />
          <stop offset="100%" stopColor="#1a110a" />
        </radialGradient>

        {/* --- HAIR: Volume Gradients --- */}
        <linearGradient id={`hair-grad-${uniqueId}`} x1="0" y1="0" x2="0" y2="1">
           <stop offset="0%" stopColor={hairLight} />
           <stop offset="50%" stopColor={hairBase} />
           <stop offset="100%" stopColor={hairDark} />
        </linearGradient>

        {/* --- CLOTHING: Fabric Shading --- */}
        <linearGradient id={`cloth-grad-${uniqueId}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor={topLight} />
          <stop offset="40%" stopColor={topBase} />
          <stop offset="100%" stopColor={topDark} />
        </linearGradient>
      </defs>

      {/* --- BACK HAIR --- */}
      <g transform="translate(0, 50)">
        {(config.hairStyle === 'long' || config.hairStyle === 'bob') && (
            <path 
              d="M80,100 Q60,150 70,240 L230,240 Q240,150 220,100" 
              fill={hairDark} 
            />
        )}

        {/* --- BODY --- */}
        <g transform="translate(0, 320)">
            {/* Legs */}
            <path d="M100,0 L95,200 L135,200 L135,0" fill={skinShadow} />
            <path d="M165,0 L165,200 L205,200 L200,0" fill={skinShadow} />

            {/* Bottoms Layer */}
            {config.bottomType === 'pants' && (
               <path 
                 d="M95,0 L85,220 L138,220 L145,40 L155,40 L162,220 L215,220 L205,0 Z" 
                 fill={botBase} 
                 stroke={botDark} strokeWidth="1"
               />
            )}
            {config.bottomType === 'shorts' && (
               <path 
                 d="M95,0 L90,100 L140,100 L145,30 L155,30 L160,100 L210,100 L205,0 Z" 
                 fill={botBase} 
                 stroke={botDark} strokeWidth="1"
               />
            )}
            {config.bottomType === 'skirt' && (
                <path d="M95,0 L65,150 Q150,170 235,150 L205,0 Z" fill={botBase} />
            )}

            {/* Shoes */}
            <g transform="translate(0, 220)">
               <path d="M85,0 Q75,10 85,30 L138,30 Q145,25 138,0 Z" fill="#111" />
               <path d="M162,0 Q155,10 162,30 L215,30 Q225,25 215,0 Z" fill="#111" />
            </g>
        </g>

        {/* --- TORSO --- */}
        <g transform="translate(0, 150)">
             {/* Neck Ambient Occlusion */}
             <path d="M130,-40 L130,20 L170,20 L170,-40" fill={skinShadow} />

             {/* Torso Base */}
             <path 
               d="M85,0 C70,20 75,160 90,185 L210,185 C225,160 230,20 215,0 Q150,-15 85,0" 
               fill={`url(#cloth-grad-${uniqueId})`}
               filter={`url(#occlusion-${uniqueId})`}
             />

             {/* Clothing Details */}
             {config.topType === 'hoodie' && (
                 <g>
                    <path d="M110,0 Q150,60 190,0" fill="none" stroke="rgba(0,0,0,0.2)" strokeWidth="8"/>
                    <path d="M130,80 Q150,140 170,80" fill="none" stroke="rgba(255,255,255,0.2)" strokeWidth="2" />
                    {/* Drawstrings */}
                    <line x1="140" y1="20" x2="140" y2="70" stroke="#eee" strokeWidth="2" strokeLinecap="round" />
                    <line x1="160" y1="20" x2="160" y2="70" stroke="#eee" strokeWidth="2" strokeLinecap="round" />
                 </g>
             )}
             {config.topType === 'suit' && (
                 <g>
                    <path d="M150,0 L150,185" stroke="rgba(0,0,0,0.1)" strokeWidth="2" />
                    <path d="M150,0 L135,45 L150,90 L165,45 Z" fill="#b00" /> {/* Tie */}
                    <path d="M110,0 L150,90 L190,0" fill="none" stroke="rgba(255,255,255,0.3)" strokeWidth="1"/>
                 </g>
             )}

             {/* Arms */}
             <g>
                 <path d="M85,20 L50,160 L85,170" fill={topBase} filter={`url(#occlusion-${uniqueId})`} />
                 <path d="M215,20 L250,160 L215,170" fill={topBase} filter={`url(#occlusion-${uniqueId})`} />
                 {/* Hands */}
                 <circle cx="67" cy="170" r="14" fill={skinBase} />
                 <circle cx="233" cy="170" r="14" fill={skinBase} />
             </g>
        </g>

        {/* ================= HEAD ================= */}
        <g transform="translate(150, 90)">
            {/* Face Shape */}
            <path 
              d="M-58,-70 C-58,-120 58,-120 58,-70 L58,25 C58,85 35,110 0,110 C-35,110 -58,85 -58,25 Z" 
              fill={`url(#skin-grad-${uniqueId})`}
              filter={`url(#occlusion-${uniqueId})`}
            />

            {/* Inner Ear Detail */}
            <g>
               <path d="M-58,-20 Q-70,-10 -58,20" fill={skinWarmth} />
               <path d="M-60,0 Q-65,0 -60,10" stroke={skinShadow} fill="none" />
               <path d="M58,-20 Q70,-10 58,20" fill={skinWarmth} />
               <path d="M60,0 Q65,0 60,10" stroke={skinShadow} fill="none" />
            </g>

            {/* Facial Features Group */}
            <g transform="translate(0, 10)">
                {/* Nose Bridge and Shadow */}
                <path d="M-6,10 Q0,5 6,10" fill="none" stroke={skinShadow} strokeWidth="1" opacity="0.4" />
                <path d="M-8,28 Q0,35 8,28" fill="none" stroke={skinShadow} strokeWidth="3" opacity="0.6" strokeLinecap="round" />

                {/* Mouth with Expression */}
                <path d="M-18,60 Q0,75 18,60" fill="none" stroke="#8d5524" strokeWidth="4" strokeLinecap="round" />

                {/* Eyes - High Definition */}
                <g transform="translate(0, -5)">
                    {/* Left Eye */}
                    <g transform="translate(-28, 0)">
                        <ellipse rx="16" ry="18" fill="#fff" />
                        {!isPirate && config.accessory !== 'sunglasses' && (
                            <>
                                <circle r="9" fill={`url(#iris-grad-${uniqueId})`} />
                                <circle r="4" fill="#000" />
                                <circle cx="4" cy="-4" r="3.5" fill="#fff" opacity="0.9" />
                                <circle cx="-3" cy="5" r="1.5" fill="#fff" opacity="0.4" />
                            </>
                        )}
                        <path d="M-16,0 Q0,-22 16,0" fill="none" stroke="rgba(0,0,0,0.1)" strokeWidth="6" />
                    </g>
                    {/* Right Eye */}
                    <g transform="translate(28, 0)">
                        <ellipse rx="16" ry="18" fill="#fff" />
                        {!isPirate && config.accessory !== 'sunglasses' && (
                            <>
                                <circle r="9" fill={`url(#iris-grad-${uniqueId})`} />
                                <circle r="4" fill="#000" />
                                <circle cx="4" cy="-4" r="3.5" fill="#fff" opacity="0.9" />
                                <circle cx="-3" cy="5" r="1.5" fill="#fff" opacity="0.4" />
                            </>
                        )}
                        <path d="M-16,0 Q0,-22 16,0" fill="none" stroke="rgba(0,0,0,0.1)" strokeWidth="6" />
                    </g>
                </g>

                {/* Brows */}
                <path d="M-45,-25 Q-30,-32 -15,-25" fill="none" stroke={hairDark} strokeWidth="5" strokeLinecap="round" />
                <path d="M45,-25 Q30,-32 15,-25" fill="none" stroke={hairDark} strokeWidth="5" strokeLinecap="round" />

                {/* Beards */}
                {config.beard === 'full' && (
                    <path d="M-58,20 Q0,110 58,20 L58,40 Q0,130 -58,40 Z" fill={hairBase} opacity="0.95" />
                )}
                {config.beard === 'mustache' && (
                    <path d="M-20,48 Q0,40 20,48 Q0,58 -20,48" fill={hairBase} />
                )}
            </g>

            {/* FRONT HAIR STYLE */}
            <g transform="translate(0, -10)">
                {config.hairStyle === 'short' && (
                    <path d="M-58,-60 Q0,-120 58,-60 Q58,-40 20,-40 Q0,-80 -58,-40 Z" fill={`url(#hair-grad-${uniqueId})`} />
                )}
                {config.hairStyle === 'spiky' && (
                    <path d="M-58,-60 L-30,-110 L0,-70 L30,-110 L58,-60 Q0,-30 -58,-60" fill={`url(#hair-grad-${uniqueId})`} />
                )}
                {config.hairStyle === 'long' && (
                    <path d="M-58,-60 Q0,-130 58,-60 L65,150 Q20,130 -10,130 L-20,150 L-65,150 Z" fill={`url(#hair-grad-${uniqueId})`} />
                )}

                {/* Hair Specular Highlights */}
                {config.hairStyle !== 'bald' && (
                   <g opacity="0.3">
                      <path d="M-30,-85 Q0,-100 30,-85" fill="none" stroke="#fff" strokeWidth="8" strokeLinecap="round" />
                      <path d="M-40,-70 Q0,-85 40,-70" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" />
                   </g>
                )}
            </g>

            {/* Accessories */}
            {config.accessory === 'glasses' && !isPirate && (
                <g transform="translate(0, 5)">
                    <circle cx="-28" cy="0" r="20" fill="none" stroke="#222" strokeWidth="3" />
                    <circle cx="28" cy="0" r="20" fill="none" stroke="#222" strokeWidth="3" />
                    <path d="M-8,0 Q0,-5 8,0" fill="none" stroke="#222" strokeWidth="3" />
                </g>
            )}
            {config.accessory === 'crown' && (
                <path d="M-40,-100 L-40,-130 L-20,-110 L0,-140 L20,-110 L40,-130 L40,-100 Z" fill="#ffd700" stroke="#daa520" strokeWidth="2" filter={`url(#occlusion-${uniqueId})`} />
            )}
        </g>
      </g>
    </svg>
  );
};

