const GameScreen: React.FC<{ user: User, difficulty: Difficulty, onExit: () => void, onScoreUpdate: (points: number) => void }> = ({ user, difficulty, onExit, onScoreUpdate }) => {
  const t = TRANSLATIONS[user.settings.language || Language.ENGLISH];
  const [status, setStatus] = useState<GameStatus>(GameStatus.LOADING);
  const [gameData, setGameData] = useState<GameData | null>(null);
  const [selectedCells, setSelectedCells] = useState<GridCell[]>([]);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [score, setScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState(120);

  const gridSize = difficulty === Difficulty.BEGINNER ? 4 : difficulty === Difficulty.NORMAL ? 5 : difficulty === Difficulty.HARD ? 6 : 7;

  useEffect(() => {
    GeminiService.generateGameLevel(gridSize).then(data => {
      setGameData(data);
      setStatus(GameStatus.PLAYING);
    });
  }, [gridSize]);

  useEffect(() => {
    if (status === GameStatus.PLAYING && timeLeft > 0) {
      const timer = setInterval(() => setTimeLeft(t => t - 1), 1000);
      return () => clearInterval(timer);
    } else if (timeLeft === 0) {
      setStatus(GameStatus.FINISHED);
      onScoreUpdate(Math.floor(score / 10));
    }
  }, [status, timeLeft]);

  const handleSubmit = () => {
    const word = selectedCells.map(c => c.char).join('');
    if (gameData?.validWords.includes(word) && !foundWords.includes(word)) {
      setScore(s => s + word.length * 100);
      setFoundWords(f => [word, ...f]);
    }
    setSelectedCells([]);
  };

  if (status === GameStatus.LOADING) return <div className="flex h-full items-center justify-center">Loading...</div>;
  if (status === GameStatus.FINISHED) return <div className="flex flex-col items-center justify-center h-full gap-4"><h1 className="text-4xl font-black">FINISHED!</h1><p className="text-2xl">Score: {score}</p><button onClick={onExit} className="p-4 bg-blue-600 text-white rounded-xl">Menu</button></div>;

  return (
    <div className="flex flex-col h-full p-4">
      <div className="flex justify-between items-center mb-4">
        <div className="font-black text-2xl">{score}</div>
        <div className="font-mono text-xl">{timeLeft}s</div>
      </div>
      <div className="flex-1 grid gap-2" style={{ gridTemplateColumns: `repeat(${gridSize}, 1fr)` }}>
        {gameData?.grid.flat().map((char, i) => (
          <button key={i} onClick={() => setSelectedCells(s => [...s, { id: `${i}`, char, x: 0, y: 0 }])} className="aspect-square bg-white/40 rounded-xl text-3xl font-black">{char}</button>
        ))}
      </div>
      <div className="h-16 flex items-center justify-center text-3xl font-black mt-4 uppercase tracking-widest">{selectedCells.map(c => c.char).join('')}</div>
      <div className="flex gap-4 mt-4">
        <button onClick={() => setSelectedCells([])} className="flex-1 p-4 bg-red-500 text-white rounded-xl font-bold">Clear</button>
        <button onClick={handleSubmit} className="flex-1 p-4 bg-green-600 text-white rounded-xl font-bold">Submit</button>
      </div>
    </div>
  );
};

