    if (saved) setUser(saved);
  }, []);

  const t = user ? TRANSLATIONS[user.settings.language] : TRANSLATIONS[Language.ENGLISH];

  return (
    <div className={`min-h-screen transition-colors duration-500 ${darkMode ? 'dark bg-slate-900 text-white' : 'bg-gray-100 text-slate-900'}`}>
