              <button onClick={() => setView('GAME')} className="p-4 bg-blue-600 text-white rounded-2xl font-black text-xl shadow-xl hover:scale-105 transition-all">{t.play}</button>
              <button onClick={() => setView('CUSTOMIZE')} className="p-4 bg-white/20 rounded-2xl font-bold flex items-center justify-center gap-2"><Shirt size={20} /> {t.customize}</button>
              <div className="flex gap-2">
