        <svg viewBox="0 0 40 40" className="w-8 h-8 fill-slate-500 dark:fill-gray-400">
            {children}
        </svg>
    );

    if (category === 'hairStyle') {
        if (value === 'bald') return <IconWrapper><circle cx="20" cy="20" r="12" opacity="0.5"/></IconWrapper>;
        return <IconWrapper><path d="M10,20 Q20,5 30,20 L30,30 Q20,25 10,30 Z" /></IconWrapper>;
    }
    if (category === 'topType') return <IconWrapper><path d="M10,10 L30,10 L32,30 L8,30 Z" /></IconWrapper>;
    if (category === 'bottomType') return <IconWrapper><path d="M10,10 L30,10 L30,30 L10,30 Z" /></IconWrapper>;
    if (category === 'beard') return <IconWrapper><path d="M10,20 Q20,35 30,20" stroke="currentColor" fill="none"/></IconWrapper>;
    if (category === 'accessory') return <IconWrapper><circle cx="20" cy="20" r="10" stroke="currentColor" fill="none" /></IconWrapper>;

    return <IconWrapper><circle cx="20" cy="20" r="10" fill="currentColor" opacity="0.2"/></IconWrapper>;
};

