const LoginScreen: React.FC<{ onLogin: (u: User) => void }> = ({ onLogin }) => {
  const [viewState, setViewState] = useState<'LOGIN' | 'REGISTER' | 'FORGOT'>('LOGIN');
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMsg(null);

    if (viewState === 'FORGOT') {
      const result = StorageService.requestPasswordReset(email);
      if (result.success) setSuccessMsg(result.message);
      else setError(result.message);
      return;
    }

    if (viewState === 'REGISTER') {
      const result = StorageService.registerUser(username, email, password);
      if (result.success && result.user) onLogin(result.user);
      else setError(result.message || "Registration failed.");
    } else {
      const result = StorageService.loginUser(username, password);
      if (result.success && result.user) onLogin(result.user);
      else setError(result.message || "Login failed.");
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] gap-8 p-4 animate-in fade-in zoom-in duration-500">
      <Logo size="lg" />
      <div className="w-full max-w-xs bg-white/60 dark:bg-black/20 backdrop-blur-xl p-6 rounded-3xl border border-black/5 dark:border-white/10 shadow-2xl">
        <h2 className="text-center text-xl font-black text-slate-900 dark:text-white mb-6 uppercase tracking-wider">
          {viewState === 'REGISTER' ? 'New Profile' : viewState === 'FORGOT' ? 'Reset Protocols' : 'Agent Login'}
        </h2>
        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          {viewState !== 'FORGOT' && (
             <div className="relative group">
               <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-atomic-blue transition-colors" size={20} />
               <input type="text" placeholder="Username" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full pl-12 pr-4 py-3 rounded-xl bg-black/5 dark:bg-white/5 border border-black/5 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-atomic-blue transition-all" />
             </div>
          )}
          {(viewState === 'REGISTER' || viewState === 'FORGOT') && (
            <div className="relative group">
              <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-atomic-orange transition-colors" size={20} />
              <input type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full pl-12 pr-4 py-3 rounded-xl bg-black/5 dark:bg-white/5 border border-black/5 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-atomic-orange transition-all" />
            </div>
          )}
          {viewState !== 'FORGOT' && (
            <div className="relative group">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-atomic-neon transition-colors" size={20} />
              <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full pl-12 pr-4 py-3 rounded-xl bg-black/5 dark:bg-white/5 border border-black/5 text-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-atomic-neon transition-all" />
            </div>
          )}
          {error && <div className="text-red-600 text-xs text-center font-bold bg-red-500/10 py-2 rounded-lg">{error}</div>}
          <button type="submit" className="mt-2 bg-gradient-to-r from-blue-600 to-cyan-500 text-white font-black py-3 rounded-xl uppercase tracking-widest hover:scale-105 transition-all shadow-lg">
            {viewState === 'REGISTER' ? 'Register' : viewState === 'FORGOT' ? 'Send Link' : 'Login'}
          </button>
        </form>
        <div className="mt-6 flex flex-col gap-2 text-center">
          {viewState === 'LOGIN' ? (
             <button onClick={() => setViewState('REGISTER')} className="text-xs text-slate-600 underline">Need an account? Register</button>
          ) : (
              <button onClick={() => setViewState('LOGIN')} className="text-xs text-slate-600 underline">Back to Login</button>
          )}
        </div>
      </div>
    </div>
  );
};

